-- ExamCore CBT database (generated 2026-11-05 from the migrations).
-- For hosts without a shell (e.g. InfinityFree phpMyAdmin): import this file into an empty database.
-- Contains the full structure plus reference data (plans, practice exams, platform question bank).
-- No schools, users or student data. Afterwards open /setup to create the owner account.
-- Table prefix: cbt_ (keep DB_PREFIX=cbt_ in .env).

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE='NO_AUTO_VALUE_ON_ZERO';

CREATE TABLE IF NOT EXISTS `cbt_academic_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `name` varchar(20) NOT NULL,
  `starts_on` date NOT NULL,
  `ends_on` date NOT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_sessions_name` (`school_id`,`name`),
  KEY `idx_cbt_sessions_current` (`school_id`,`is_current`),
  CONSTRAINT `fk_cbt_sessions_school` FOREIGN KEY (`school_id`) REFERENCES `cbt_schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_attempt_answers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `attempt_id` bigint(20) unsigned NOT NULL,
  `question_id` bigint(20) unsigned NOT NULL,
  `selected_option` char(1) DEFAULT NULL,
  `is_correct` tinyint(1) DEFAULT NULL,
  `is_flagged` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_attempt_answers_attempt_question` (`attempt_id`,`question_id`),
  KEY `idx_cbt_attempt_answers_question` (`question_id`),
  CONSTRAINT `fk_cbt_attempt_answers_attempt` FOREIGN KEY (`attempt_id`) REFERENCES `cbt_attempts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cbt_attempt_answers_question` FOREIGN KEY (`question_id`) REFERENCES `cbt_questions` (`id`),
  CONSTRAINT `chk_cbt_attempt_answers_option` CHECK (`selected_option` is null or `selected_option` in ('A','B','C','D'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_attempts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exam_id` bigint(20) unsigned NOT NULL,
  `session_token` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `student_name` varchar(80) DEFAULT NULL,
  `student_email` varchar(180) DEFAULT NULL,
  `access_token` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `multi_exam` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`multi_exam`)),
  `question_order` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`question_order`)),
  `started_at` datetime NOT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `score` decimal(9,2) DEFAULT NULL,
  `total` decimal(9,2) NOT NULL DEFAULT 0.00,
  `duration_minutes` smallint(5) unsigned DEFAULT NULL,
  `status` enum('in_progress','submitted','timed_out') NOT NULL DEFAULT 'in_progress',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_attempts_access_token` (`access_token`),
  KEY `idx_cbt_attempts_session_recent` (`session_token`,`started_at`),
  KEY `idx_cbt_attempts_exam_status` (`exam_id`,`status`),
  KEY `idx_cbt_attempts_student_email` (`student_email`),
  KEY `idx_cbt_attempts_status_started` (`status`,`started_at`),
  CONSTRAINT `fk_cbt_attempts_exam` FOREIGN KEY (`exam_id`) REFERENCES `cbt_exams` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_audit_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned DEFAULT NULL,
  `actor_id` bigint(20) unsigned DEFAULT NULL,
  `actor_name` varchar(120) DEFAULT NULL,
  `impersonator_id` bigint(20) unsigned DEFAULT NULL,
  `action` varchar(80) NOT NULL,
  `target_type` varchar(40) DEFAULT NULL,
  `target_id` bigint(20) unsigned DEFAULT NULL,
  `summary` varchar(255) NOT NULL,
  `meta` text DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cbt_audit_school_time` (`school_id`,`created_at`),
  KEY `idx_cbt_audit_actor` (`actor_id`,`created_at`),
  KEY `idx_cbt_audit_action` (`action`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_bank_passages` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned DEFAULT NULL,
  `subject` varchar(80) NOT NULL,
  `title` varchar(160) NOT NULL,
  `body` mediumtext NOT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cbt_passages_scope` (`school_id`,`subject`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_bank_questions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned DEFAULT NULL,
  `subject` varchar(80) NOT NULL,
  `topic` varchar(120) DEFAULT NULL,
  `level` varchar(10) NOT NULL DEFAULT 'any',
  `difficulty` enum('easy','medium','hard') NOT NULL DEFAULT 'medium',
  `exam_body` varchar(10) DEFAULT NULL,
  `year` smallint(5) unsigned DEFAULT NULL,
  `source` enum('teacher','practice','past_licensed','ai_reviewed') NOT NULL DEFAULT 'teacher',
  `passage_id` bigint(20) unsigned DEFAULT NULL,
  `body` text NOT NULL,
  `image_path` varchar(255) DEFAULT NULL,
  `option_a` text NOT NULL,
  `option_b` text NOT NULL,
  `option_c` text DEFAULT NULL,
  `option_d` text DEFAULT NULL,
  `option_e` text DEFAULT NULL,
  `correct_option` char(1) NOT NULL,
  `explanation` text DEFAULT NULL,
  `marks` decimal(5,2) NOT NULL DEFAULT 1.00,
  `status` enum('draft','review','published','archived') NOT NULL DEFAULT 'draft',
  `review_note` varchar(255) DEFAULT NULL,
  `fingerprint` char(40) NOT NULL,
  `times_answered` int(10) unsigned NOT NULL DEFAULT 0,
  `times_correct` int(10) unsigned NOT NULL DEFAULT 0,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `reviewed_by` bigint(20) unsigned DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cbt_bank_scope` (`school_id`,`subject`,`status`),
  KEY `idx_cbt_bank_status` (`school_id`,`status`,`updated_at`),
  KEY `idx_cbt_bank_author` (`school_id`,`created_by`),
  KEY `idx_cbt_bank_fingerprint` (`school_id`,`fingerprint`),
  KEY `fk_cbt_bank_passage` (`passage_id`),
  FULLTEXT KEY `ft_cbt_bank_body` (`body`),
  CONSTRAINT `fk_cbt_bank_passage` FOREIGN KEY (`passage_id`) REFERENCES `cbt_bank_passages` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_cbt_bank_answer` CHECK (`correct_option` in ('A','B','C','D','E'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_class_subjects` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `class_id` bigint(20) unsigned NOT NULL,
  `subject_id` bigint(20) unsigned NOT NULL,
  `teacher_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_class_subject` (`class_id`,`subject_id`),
  KEY `idx_cbt_class_subjects_teacher` (`school_id`,`teacher_id`),
  KEY `fk_cbt_cs_subject` (`subject_id`),
  KEY `fk_cbt_cs_teacher` (`teacher_id`),
  CONSTRAINT `fk_cbt_cs_class` FOREIGN KEY (`class_id`) REFERENCES `cbt_school_classes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cbt_cs_subject` FOREIGN KEY (`subject_id`) REFERENCES `cbt_school_subjects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cbt_cs_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `cbt_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_departments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `name` varchar(60) NOT NULL,
  `code` varchar(12) DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_departments_name` (`school_id`,`name`),
  CONSTRAINT `fk_cbt_departments_school` FOREIGN KEY (`school_id`) REFERENCES `cbt_schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_exam_sitting_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sitting_id` bigint(20) unsigned NOT NULL,
  `type` varchar(30) NOT NULL,
  `detail` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cbt_sevent_sitting` (`sitting_id`,`id`),
  CONSTRAINT `fk_cbt_sevent_sitting` FOREIGN KEY (`sitting_id`) REFERENCES `cbt_exam_sittings` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_exam_sitting_items` (
  `sitting_id` bigint(20) unsigned NOT NULL,
  `position` smallint(5) unsigned NOT NULL,
  `paper_id` bigint(20) unsigned NOT NULL,
  `question_id` bigint(20) unsigned NOT NULL,
  `option_order` varchar(5) NOT NULL,
  `answer` char(1) DEFAULT NULL,
  `flagged` tinyint(1) NOT NULL DEFAULT 0,
  `answered_at` datetime DEFAULT NULL,
  PRIMARY KEY (`sitting_id`,`position`),
  CONSTRAINT `fk_cbt_sitem_sitting` FOREIGN KEY (`sitting_id`) REFERENCES `cbt_exam_sittings` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_exam_sittings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `exam_id` bigint(20) unsigned NOT NULL,
  `student_id` bigint(20) unsigned NOT NULL,
  `status` enum('in_progress','submitted','auto_submitted') NOT NULL DEFAULT 'in_progress',
  `started_at` datetime NOT NULL,
  `deadline_at` datetime NOT NULL,
  `extra_minutes` smallint(5) unsigned NOT NULL DEFAULT 0,
  `submitted_at` datetime DEFAULT NULL,
  `last_seen_at` datetime DEFAULT NULL,
  `current_position` smallint(5) unsigned NOT NULL DEFAULT 1,
  `question_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `answered_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `score` smallint(5) unsigned DEFAULT NULL,
  `percent` decimal(5,2) DEFAULT NULL,
  `breakdown` text DEFAULT NULL,
  `warnings` smallint(5) unsigned NOT NULL DEFAULT 0,
  `face_status` enum('none','verified','mismatch','approved') NOT NULL DEFAULT 'none',
  `face_score` decimal(5,3) DEFAULT NULL,
  `flags` smallint(5) unsigned NOT NULL DEFAULT 0,
  `seat_no` varchar(12) DEFAULT NULL,
  `device_hash` char(64) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_sitting_student` (`exam_id`,`student_id`),
  KEY `idx_cbt_sitting_status` (`exam_id`,`status`),
  KEY `idx_cbt_sitting_deadline` (`status`,`deadline_at`),
  KEY `idx_cbt_sitting_student` (`school_id`,`student_id`),
  CONSTRAINT `fk_cbt_sitting_exam` FOREIGN KEY (`exam_id`) REFERENCES `cbt_school_exams` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_exam_snapshots` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sitting_id` bigint(20) unsigned NOT NULL,
  `kind` enum('verify','random') NOT NULL DEFAULT 'random',
  `path` varchar(255) NOT NULL,
  `faces` tinyint(3) unsigned DEFAULT NULL,
  `match_score` decimal(5,3) DEFAULT NULL,
  `flag` varchar(20) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cbt_snap_sitting` (`sitting_id`,`id`),
  KEY `idx_cbt_snap_created` (`created_at`),
  CONSTRAINT `fk_cbt_snap_sitting` FOREIGN KEY (`sitting_id`) REFERENCES `cbt_exam_sittings` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_exam_types` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(40) NOT NULL,
  `name` varchar(100) NOT NULL,
  `description` varchar(255) NOT NULL DEFAULT '',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_exam_types_slug` (`slug`),
  KEY `idx_cbt_exam_types_active` (`is_active`,`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_exams` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exam_type_id` bigint(20) unsigned NOT NULL,
  `subject_id` bigint(20) unsigned NOT NULL,
  `year` smallint(5) unsigned NOT NULL,
  `title` varchar(180) NOT NULL,
  `duration_minutes` smallint(5) unsigned NOT NULL DEFAULT 15,
  `total_questions` smallint(5) unsigned NOT NULL DEFAULT 10,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_exam_type_subject_year` (`exam_type_id`,`subject_id`,`year`),
  KEY `idx_cbt_exams_available` (`exam_type_id`,`subject_id`,`is_active`,`year`),
  KEY `fk_cbt_exams_subject` (`subject_id`),
  CONSTRAINT `fk_cbt_exams_exam_type` FOREIGN KEY (`exam_type_id`) REFERENCES `cbt_exam_types` (`id`),
  CONSTRAINT `fk_cbt_exams_subject` FOREIGN KEY (`subject_id`) REFERENCES `cbt_subjects` (`id`),
  CONSTRAINT `chk_cbt_exams_duration` CHECK (`duration_minutes` > 0),
  CONSTRAINT `chk_cbt_exams_questions` CHECK (`total_questions` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_grading_scales` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `grade` varchar(4) NOT NULL,
  `min_score` decimal(5,2) NOT NULL,
  `max_score` decimal(5,2) NOT NULL,
  `remark` varchar(40) NOT NULL,
  `is_pass` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_grades` (`school_id`,`grade`),
  CONSTRAINT `fk_cbt_grades_school` FOREIGN KEY (`school_id`) REFERENCES `cbt_schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_import_batches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `kind` varchar(20) NOT NULL,
  `status` enum('ready','processing','completed','cancelled') NOT NULL DEFAULT 'ready',
  `file_name` varchar(190) DEFAULT NULL,
  `total_rows` int(10) unsigned NOT NULL DEFAULT 0,
  `processed_rows` int(10) unsigned NOT NULL DEFAULT 0,
  `created_rows` int(10) unsigned NOT NULL DEFAULT 0,
  `skipped_rows` int(10) unsigned NOT NULL DEFAULT 0,
  `payload` mediumtext NOT NULL,
  `credentials` mediumtext DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cbt_imports_school` (`school_id`,`created_at`),
  CONSTRAINT `fk_cbt_imports_school` FOREIGN KEY (`school_id`) REFERENCES `cbt_schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(100) NOT NULL,
  `payload` text NOT NULL,
  `attempts` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `max_attempts` tinyint(3) unsigned NOT NULL DEFAULT 3,
  `available_at` datetime NOT NULL,
  `reserved_at` datetime DEFAULT NULL,
  `reservation` char(32) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `failed_at` datetime DEFAULT NULL,
  `last_error` varchar(1000) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cbt_jobs_ready` (`failed_at`,`reserved_at`,`available_at`),
  KEY `idx_cbt_jobs_reservation` (`reservation`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_migrations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(190) NOT NULL,
  `batch` int(10) unsigned NOT NULL,
  `ran_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_migration` (`migration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_plans` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(30) NOT NULL,
  `name` varchar(80) NOT NULL,
  `description` varchar(255) NOT NULL DEFAULT '',
  `price_per_student_kobo` int(10) unsigned NOT NULL DEFAULT 0,
  `billing_period` enum('term','month','year') NOT NULL DEFAULT 'term',
  `max_students` int(10) unsigned DEFAULT NULL,
  `features` text NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` smallint(5) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_plans_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_questions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exam_id` bigint(20) unsigned NOT NULL,
  `question_text` text NOT NULL,
  `option_a` text NOT NULL,
  `option_b` text NOT NULL,
  `option_c` text NOT NULL,
  `option_d` text NOT NULL,
  `correct_option` char(1) NOT NULL,
  `explanation` text NOT NULL,
  `marks` decimal(7,2) NOT NULL DEFAULT 1.00,
  `sort_order` smallint(5) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_questions_exam_order` (`exam_id`,`sort_order`),
  CONSTRAINT `fk_cbt_questions_exam` FOREIGN KEY (`exam_id`) REFERENCES `cbt_exams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_cbt_questions_correct_option` CHECK (`correct_option` in ('A','B','C','D')),
  CONSTRAINT `chk_cbt_questions_marks` CHECK (`marks` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_report_remarks` (
  `school_id` bigint(20) unsigned NOT NULL,
  `term_id` bigint(20) unsigned NOT NULL,
  `student_id` bigint(20) unsigned NOT NULL,
  `teacher_comment` varchar(400) DEFAULT NULL,
  `principal_comment` varchar(400) DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`term_id`,`student_id`),
  KEY `idx_cbt_remarks_school` (`school_id`,`term_id`),
  CONSTRAINT `fk_cbt_remarks_school` FOREIGN KEY (`school_id`) REFERENCES `cbt_schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_school_classes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `level` varchar(20) NOT NULL,
  `level_order` tinyint(3) unsigned NOT NULL,
  `arm` varchar(20) NOT NULL DEFAULT 'A',
  `name` varchar(50) NOT NULL,
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `class_teacher_id` bigint(20) unsigned DEFAULT NULL,
  `capacity` smallint(5) unsigned DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_classes_level_arm` (`school_id`,`level`,`arm`),
  KEY `idx_cbt_classes_order` (`school_id`,`level_order`,`arm`),
  KEY `fk_cbt_classes_department` (`department_id`),
  KEY `fk_cbt_classes_teacher` (`class_teacher_id`),
  CONSTRAINT `fk_cbt_classes_department` FOREIGN KEY (`department_id`) REFERENCES `cbt_departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cbt_classes_school` FOREIGN KEY (`school_id`) REFERENCES `cbt_schools` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cbt_classes_teacher` FOREIGN KEY (`class_teacher_id`) REFERENCES `cbt_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_school_exam_classes` (
  `exam_id` bigint(20) unsigned NOT NULL,
  `class_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`exam_id`,`class_id`),
  KEY `idx_cbt_sec_class` (`class_id`),
  CONSTRAINT `fk_cbt_sec_class` FOREIGN KEY (`class_id`) REFERENCES `cbt_school_classes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cbt_sec_exam` FOREIGN KEY (`exam_id`) REFERENCES `cbt_school_exams` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_school_exam_papers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exam_id` bigint(20) unsigned NOT NULL,
  `subject` varchar(80) NOT NULL,
  `mode` enum('random','fixed') NOT NULL DEFAULT 'random',
  `question_count` smallint(5) unsigned NOT NULL DEFAULT 20,
  `topics` text DEFAULT NULL,
  `difficulty` varchar(10) DEFAULT NULL,
  `position` tinyint(3) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_paper_subject` (`exam_id`,`subject`),
  CONSTRAINT `fk_cbt_papers_exam` FOREIGN KEY (`exam_id`) REFERENCES `cbt_school_exams` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_school_exam_questions` (
  `paper_id` bigint(20) unsigned NOT NULL,
  `question_id` bigint(20) unsigned NOT NULL,
  `position` smallint(5) unsigned NOT NULL,
  PRIMARY KEY (`paper_id`,`question_id`),
  KEY `fk_cbt_seq_question` (`question_id`),
  CONSTRAINT `fk_cbt_seq_paper` FOREIGN KEY (`paper_id`) REFERENCES `cbt_school_exam_papers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cbt_seq_question` FOREIGN KEY (`question_id`) REFERENCES `cbt_bank_questions` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_school_exams` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `term_id` bigint(20) unsigned DEFAULT NULL,
  `title` varchar(160) NOT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'test',
  `status` enum('draft','published','cancelled') NOT NULL DEFAULT 'draft',
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `duration_minutes` smallint(5) unsigned NOT NULL,
  `instructions` text DEFAULT NULL,
  `settings` text NOT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `results_released_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cbt_sexams_window` (`school_id`,`status`,`starts_at`),
  KEY `idx_cbt_sexams_author` (`school_id`,`created_by`),
  KEY `idx_cbt_sexams_term` (`school_id`,`term_id`,`status`),
  CONSTRAINT `fk_cbt_sexams_school` FOREIGN KEY (`school_id`) REFERENCES `cbt_schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_school_subjects` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `name` varchar(80) NOT NULL,
  `code` varchar(12) DEFAULT NULL,
  `category` varchar(20) NOT NULL DEFAULT 'general',
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_subjects_name` (`school_id`,`name`),
  KEY `idx_cbt_subjects_category` (`school_id`,`category`,`is_active`),
  KEY `fk_cbt_school_subjects_department` (`department_id`),
  CONSTRAINT `fk_cbt_school_subjects_department` FOREIGN KEY (`department_id`) REFERENCES `cbt_departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cbt_school_subjects_school` FOREIGN KEY (`school_id`) REFERENCES `cbt_schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_schools` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(60) NOT NULL,
  `name` varchar(160) NOT NULL,
  `short_name` varchar(40) DEFAULT NULL,
  `motto` varchar(160) DEFAULT NULL,
  `status` enum('trial','active','suspended','archived') NOT NULL DEFAULT 'trial',
  `plan_id` int(10) unsigned NOT NULL,
  `max_students_override` int(10) unsigned DEFAULT NULL,
  `trial_ends_at` date DEFAULT NULL,
  `subscription_ends_at` date DEFAULT NULL,
  `email` varchar(180) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `state` varchar(60) DEFAULT NULL,
  `country` varchar(60) NOT NULL DEFAULT 'Nigeria',
  `logo_path` varchar(255) DEFAULT NULL,
  `primary_color` char(7) NOT NULL DEFAULT '#1E40AF',
  `report_settings` text DEFAULT NULL,
  `custom_domain` varchar(190) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_schools_slug` (`slug`),
  UNIQUE KEY `uq_cbt_schools_domain` (`custom_domain`),
  KEY `idx_cbt_schools_status` (`status`,`created_at`),
  KEY `fk_cbt_schools_plan` (`plan_id`),
  CONSTRAINT `fk_cbt_schools_plan` FOREIGN KEY (`plan_id`) REFERENCES `cbt_plans` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_staff_profiles` (
  `user_id` bigint(20) unsigned NOT NULL,
  `school_id` bigint(20) unsigned NOT NULL,
  `title` varchar(12) DEFAULT NULL,
  `staff_no` varchar(40) DEFAULT NULL,
  `qualification` varchar(120) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uq_cbt_staff_no` (`school_id`,`staff_no`),
  CONSTRAINT `fk_cbt_staff_user` FOREIGN KEY (`user_id`) REFERENCES `cbt_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_student_profiles` (
  `user_id` bigint(20) unsigned NOT NULL,
  `school_id` bigint(20) unsigned NOT NULL,
  `admission_no` varchar(40) NOT NULL,
  `class_id` bigint(20) unsigned DEFAULT NULL,
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `gender` enum('female','male') DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `guardian_name` varchar(120) DEFAULT NULL,
  `guardian_phone` varchar(30) DEFAULT NULL,
  `guardian_email` varchar(180) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `photo_path` varchar(255) DEFAULT NULL,
  `result_code` char(8) DEFAULT NULL,
  `status` enum('active','graduated','withdrawn','suspended') NOT NULL DEFAULT 'active',
  `admitted_on` date DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uq_cbt_students_admission` (`school_id`,`admission_no`),
  KEY `idx_cbt_students_class` (`school_id`,`class_id`,`status`),
  KEY `idx_cbt_students_status` (`school_id`,`status`),
  KEY `fk_cbt_students_class` (`class_id`),
  KEY `fk_cbt_students_department` (`department_id`),
  KEY `idx_cbt_students_phone` (`school_id`,`guardian_phone`),
  CONSTRAINT `fk_cbt_students_class` FOREIGN KEY (`class_id`) REFERENCES `cbt_school_classes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cbt_students_department` FOREIGN KEY (`department_id`) REFERENCES `cbt_departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cbt_students_user` FOREIGN KEY (`user_id`) REFERENCES `cbt_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_subjects` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(60) NOT NULL,
  `name` varchar(100) NOT NULL,
  `icon` varchar(40) NOT NULL DEFAULT 'book-open',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_subjects_slug` (`slug`),
  KEY `idx_cbt_subjects_active` (`is_active`,`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_terms` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `session_id` bigint(20) unsigned NOT NULL,
  `position` tinyint(3) unsigned NOT NULL,
  `name` varchar(30) NOT NULL,
  `starts_on` date DEFAULT NULL,
  `ends_on` date DEFAULT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_terms_position` (`session_id`,`position`),
  KEY `idx_cbt_terms_current` (`school_id`,`is_current`),
  CONSTRAINT `fk_cbt_terms_session` FOREIGN KEY (`session_id`) REFERENCES `cbt_academic_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `cbt_users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned DEFAULT NULL,
  `role` enum('owner','school_admin','teacher','reviewer','student') NOT NULL,
  `name` varchar(120) NOT NULL,
  `email` varchar(180) DEFAULT NULL,
  `username` varchar(60) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `password_hash` varchar(255) NOT NULL,
  `status` enum('active','disabled') NOT NULL DEFAULT 'active',
  `must_change_password` tinyint(1) NOT NULL DEFAULT 0,
  `two_factor_secret` varchar(255) DEFAULT NULL,
  `two_factor_confirmed_at` datetime DEFAULT NULL,
  `two_factor_recovery_codes` text DEFAULT NULL,
  `two_factor_last_step` int(10) unsigned DEFAULT NULL,
  `failed_logins` smallint(5) unsigned NOT NULL DEFAULT 0,
  `locked_until` datetime DEFAULT NULL,
  `last_login_at` datetime DEFAULT NULL,
  `last_login_ip` varchar(45) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `email_scope` varchar(200) GENERATED ALWAYS AS (if(`email` is null,NULL,concat(coalesce(`school_id`,0),':',`email`))) STORED,
  `username_scope` varchar(80) GENERATED ALWAYS AS (if(`username` is null,NULL,concat(coalesce(`school_id`,0),':',`username`))) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cbt_users_email_scope` (`email_scope`),
  UNIQUE KEY `uq_cbt_users_username_scope` (`username_scope`),
  KEY `idx_cbt_users_email` (`email`),
  KEY `idx_cbt_users_school_role` (`school_id`,`role`,`status`),
  KEY `idx_cbt_users_school_role_name` (`school_id`,`role`,`name`),
  KEY `idx_cbt_users_school_role_id` (`school_id`,`role`),
  FULLTEXT KEY `ft_cbt_users_name` (`name`),
  CONSTRAINT `fk_cbt_users_school` FOREIGN KEY (`school_id`) REFERENCES `cbt_schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



SET FOREIGN_KEY_CHECKS=1;
