INSERT  IGNORE INTO `cbt_questions` VALUES (1,1,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (2,1,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (3,1,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (4,1,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (5,1,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (6,1,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (7,1,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (8,1,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (9,1,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (10,1,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (11,2,'Choose the word nearest in meaning to \"concise\".','Brief','Confusing','Detailed','Uncertain','A','Concise means expressed clearly in few words, or brief.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (12,2,'Choose the correct completion: Neither the teacher nor the students ___ ready.','is','was','are','has','C','With neither/nor, the verb agrees with the nearer subject, \"students\".',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (13,2,'Which word is opposite in meaning to \"scarce\"?','Rare','Plentiful','Limited','Uncommon','B','Plentiful means available in large quantities, the opposite of scarce.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (14,2,'Select the correctly punctuated sentence.','After lunch we returned, to class.','After lunch, we returned to class.','After, lunch we returned to class.','After lunch we, returned to class.','B','The introductory phrase is followed by a comma; the subject and verb stay together.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (15,2,'In \"The committee reached a unanimous decision,\" what does \"unanimous\" mean?','Made quickly','Made by everyone in agreement','Made in secret','Made after a debate','B','A unanimous decision is one supported by all members.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (16,2,'Choose the correct word: She has lived in Abuja ___ 2020.','for','since','during','by','B','\"Since\" introduces the starting point of a period that continues to the present.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (17,2,'Which sentence is in the passive voice?','The team solved the problem.','The problem was solved by the team.','The team is solving the problem.','The team will solve the problem.','B','The subject \"problem\" receives the action in \"was solved\".',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (18,2,'Choose the correctly spelt word.','Accomodation','Acommodation','Accommodation','Accommondation','C','The standard spelling is accommodation, with double c and double m.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (19,2,'What is the function of \"although\" in \"Although it rained, the match continued\"?','It introduces a contrast.','It gives a reason.','It states a result.','It gives an example.','A','Although introduces a contrast between the rain and the match continuing.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (20,2,'Choose the correct reported form: Musa said, \"I am tired.\"','Musa said that I am tired.','Musa said that he was tired.','Musa says that he tired.','Musa said he is tiring.','B','In reported speech, the pronoun changes to he and the present tense shifts to past.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (21,3,'Which organelle is the main site of aerobic respiration in a cell?','Ribosome','Mitochondrion','Golgi apparatus','Vacuole','B','Mitochondria release energy through aerobic respiration.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (22,3,'Which process produces glucose in green plants?','Transpiration','Respiration','Photosynthesis','Fermentation','C','Photosynthesis uses light energy, carbon dioxide, and water to produce glucose.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (23,3,'What is the basic structural and functional unit of life?','Tissue','Organ','Cell','System','C','The cell is the smallest unit capable of carrying out life processes.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (24,3,'Which blood component transports most oxygen?','Platelets','Red blood cells','Plasma','White blood cells','B','Haemoglobin in red blood cells binds and transports most oxygen.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (25,3,'The transfer of pollen from anther to stigma is called what?','Fertilisation','Pollination','Germination','Dispersal','B','Pollination is the transfer of pollen grains to a flower stigma.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (26,3,'Which organism is a primary consumer in a grassland food chain?','Grass','Grasshopper','Snake','Hawk','B','A grasshopper feeds on producers such as grass, so it is a primary consumer.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (27,3,'Which part of the human kidney filters blood?','Nephron','Alveolus','Neuron','Villus','A','Each nephron filters blood and helps form urine.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (28,3,'What is the term for an organism\'s observable characteristics?','Genotype','Phenotype','Allele','Mutation','B','Phenotype describes observable traits produced by genes and environment.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (29,3,'Which gas is released by plants during photosynthesis?','Nitrogen','Carbon dioxide','Oxygen','Methane','C','Oxygen is released when water molecules are split during photosynthesis.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (30,3,'What is the main role of decomposers in an ecosystem?','Make sunlight','Recycle nutrients','Produce oxygen only','Control rainfall','B','Decomposers break down dead material and return nutrients to the ecosystem.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (33,1,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (34,1,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (35,1,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (36,1,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (37,1,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (38,1,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (39,1,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (40,1,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (41,1,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (42,1,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (43,1,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (44,1,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (45,1,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (46,1,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (47,1,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (48,1,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (49,1,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (50,1,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (51,1,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (52,1,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (53,1,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (54,1,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (55,1,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (56,1,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (57,1,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (58,1,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (59,1,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (60,1,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (61,1,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (62,1,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (63,2,'Choose the word nearest in meaning to \"diligent\" in the sentence: The diligent student revised every evening.','Careless','Hard-working','Impatient','Uncertain','B','Diligent means showing steady, careful effort.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (64,2,'Choose the word opposite in meaning to \"expand\" as used in: The committee plans to expand the programme.','Enlarge','Extend','Reduce','Develop','C','Reduce is the opposite of expand.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (65,2,'Select the correct completion: Each of the players ___ received a medal.','have','has','are','were','B','The subject \"each\" is singular and takes \"has\".',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (66,2,'Choose the correct completion: The information ___ useful to the new students.','are','were','is','have been','C','Information is an uncountable singular noun and takes \"is\".',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (67,2,'Which sentence uses the apostrophe correctly to show that the books belong to several teachers?','The teachers book are new.','The teacher\'s books are new.','The teachers\' books are new.','The teachers\'s books are new.','C','The plural possessive is formed by placing the apostrophe after the plural noun.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (68,2,'Choose the sentence with correct subject-verb agreement.','The list of items are on the desk.','The list of items is on the desk.','The list of items were on the desk.','The list of items have been on the desk.','B','The head noun is \"list\", which is singular; the phrase \"of items\" does not change it.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (69,2,'In the sentence \"Because the road was flooded, the team arrived late,\" what does the opening clause express?','A contrast','A reason','A comparison','A purpose','B','The flooded road is the reason the team arrived late.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (70,2,'Select the correctly spelt word.','Seperate','Separate','Seperete','Sepparate','B','The standard spelling is separate.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (71,2,'Choose the word that best completes the sentence: The witness gave a ___ account of the event.','reliable','rely','reliably','reliability','A','An adjective is required before the noun \"account\"; \"reliable\" fits.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (72,2,'Choose the correct reported form: \"We will return tomorrow,\" the visitors said.','The visitors said they will return tomorrow.','The visitors said that they would return the next day.','The visitors say they returned tomorrow.','The visitors said that we return the next day.','B','Reported future shifts from will to would, and tomorrow becomes the next day.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (73,2,'Which option is a complete sentence?','Although the rain stopped.','When the bus reached the station.','The candidates waited outside the hall.','After the long examination.','C','This option contains a subject and a complete predicate without a dependent clause.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (74,2,'Choose the correct preposition: The principal congratulated the team ___ its performance.','for','with','at','by','A','The standard collocation is congratulate someone for an achievement.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (75,2,'In \"The evidence was compelling,\" what does \"compelling\" mean?','Difficult to find','Strong and convincing','Unrelated to the claim','Based on a guess','B','Compelling evidence is strong enough to persuade.',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (76,2,'Select the correctly punctuated direct speech.','Amina said \"I have finished\".','Amina said, \"I have finished.\"','Amina said \"I have finished.\",','Amina, said, \"I have finished\".','B','A comma introduces the quotation and the full stop is placed inside the closing quotation mark.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (77,2,'Choose the appropriate conjunction: The class practised daily, ___ its accuracy improved.','so','unless','although','whereas','A','\"So\" introduces the result of practising daily.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (78,2,'Which sentence uses \"fewer\" correctly?','There is fewer water in the tank.','The class made fewer errors this week.','She has fewer patience today.','We need fewer information.','B','Fewer is used with countable plural nouns such as errors.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (79,2,'Choose the correct completion: If Chidi ___ earlier, he would have caught the first bus.','leaves','left','had left','will leave','C','The third conditional uses if + past perfect and would have + past participle.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (80,2,'Choose the correct comparative form of \"careful\".','Carefuller','More careful','Most careful','Carefulest','B','For this multi-syllable adjective, the comparative is \"more careful\".',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (81,2,'What is the function of the semicolon in \"The first trial failed; the second succeeded\"?','It joins two closely related independent clauses.','It introduces a list.','It marks a question.','It replaces an apostrophe.','A','A semicolon can join two independent clauses that are closely connected in meaning.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (82,2,'Choose the word nearest in meaning to \"reluctant\".','Unwilling','Excited','Certain','Carefree','A','Reluctant means hesitant or unwilling.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (83,2,'Select the correct completion: The news ___ spread quickly through the town.','have','has','are','were','B','News is grammatically singular and takes \"has\".',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (84,2,'Which sentence is in the active voice?','The report was prepared by the group.','The group prepared the report.','The report is being prepared.','The report had been prepared.','B','The subject \"group\" performs the action in the active sentence.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (86,2,'Choose the correct completion: The students, together with their tutor, ___ attending the workshop.','is','was','are','has','C','The main subject \"students\" is plural; the intervening phrase does not change agreement.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (87,2,'In \"The manager postponed the meeting because the report was incomplete,\" which clause gives the reason?','The manager postponed the meeting.','The report was incomplete.','The meeting was postponed.','The manager was incomplete.','B','The clause introduced by \"because\" states the reason for postponement.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (88,2,'Choose the appropriate word: The twins were born ___ the same day.','in','on','at','by','B','\"On\" is used with a specific day or date.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (89,2,'Choose the word nearest in meaning to \"obstacle\".','Advantage','Barrier','Reward','Direction','B','An obstacle is something that blocks progress, a barrier.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (90,2,'Which sentence correctly uses \"their\"?','The school changed their timetable.','The students placed their books on the shelf.','Their going to the library now.','The book is over their.','B','\"Their\" is a possessive determiner referring to the students.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (91,2,'Choose the correct completion: No sooner had the bell rung ___ the candidates entered the hall.','when','than','while','then','B','The fixed construction is \"no sooner ... than\".',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (92,2,'Choose the word opposite in meaning to \"transparent\" when describing a decision process.','Clear','Open','Secretive','Simple','C','A secretive process is the opposite of a transparent one.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (93,3,'A plant cell is placed in a concentrated salt solution and loses water. Which process explains the movement of water?','Diffusion','Osmosis','Active transport','Translocation','B','Water moves across a selectively permeable membrane from higher water potential to lower water potential by osmosis.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (94,3,'Which tissue carries water and dissolved mineral salts from roots towards the leaves?','Phloem','Xylem','Epidermis','Cambium','B','Xylem vessels transport water and mineral salts from roots through the plant.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (95,3,'Which organ produces bile, a substance that helps emulsify fats during digestion?','Pancreas','Liver','Stomach','Small intestine','B','The liver produces bile; the gall bladder stores and releases it.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (96,3,'A heterozygous tall plant is crossed with a dwarf plant. If tallness is dominant, what proportion of offspring is expected to be tall?','One quarter','One half','Three quarters','All offspring','B','Tt crossed with tt gives half Tt tall offspring and half tt dwarf offspring.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (97,3,'Which part of a flower receives pollen grains during pollination?','Anther','Stigma','Ovary','Filament','B','The stigma is the receptive surface for pollen grains.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (98,3,'Which process releases energy from glucose in the cells of animals?','Photosynthesis','Respiration','Transpiration','Excretion','B','Cellular respiration releases usable energy from glucose.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (99,3,'Which blood vessel carries blood away from the heart?','Vein','Artery','Capillary','Venule','B','Arteries carry blood away from the heart, irrespective of oxygen content.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (100,3,'A population of insects increases after its main predator becomes scarce. Which ecological relationship has changed?','Predation','Commensalism','Pollination','Parasitism','A','Reduced predation can allow prey numbers to rise.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (101,3,'Which structure in the human respiratory system is the main site of gaseous exchange?','Trachea','Bronchus','Alveolus','Larynx','C','Thin-walled alveoli provide a large surface area for oxygen and carbon dioxide exchange.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (102,3,'Which nutrient is the primary immediate source of energy in a balanced diet?','Carbohydrate','Vitamin','Mineral salt','Water','A','Carbohydrates are commonly broken down to provide energy for cellular activities.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (103,3,'What is the role of chlorophyll in a green leaf?','Absorb light energy','Transport sugars','Store mineral salts','Open the stomata','A','Chlorophyll absorbs light energy used in photosynthesis.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (104,3,'Which plant response causes a shoot to bend towards a source of light?','Geotropism','Phototropism','Hydrotropism','Thigmotropism','B','Phototropism is directional growth in response to light.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (105,3,'Which cells in the pancreas release insulin into the blood?','Beta cells','Red blood cells','Nerve cells','Goblet cells','A','Pancreatic beta cells produce insulin, which helps regulate blood glucose.',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (106,3,'Which feature of a fish helps it maintain balance and control movement in water?','Swim bladder only','Fins','Gill rakers','Scales','B','Fins provide steering, stability, and propulsion.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (107,3,'Which microorganism is commonly used in baking to make dough rise?','Yeast','Amoeba','Plasmodium','Rhizobium','A','Yeast ferments sugars and releases carbon dioxide, which expands dough.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (108,3,'Which term describes animals that maintain a relatively constant internal body temperature?','Ectothermic','Endothermic','Anaerobic','Aquatic','B','Endothermic animals generate and regulate body heat internally.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (109,3,'What is the main function of root hairs in a plant?','Absorb water and mineral ions','Make seeds','Carry sugars to flowers','Prevent pollination','A','Root hairs increase surface area for absorption from the soil.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (110,3,'Which structure prevents food from entering the trachea during swallowing?','Epiglottis','Diaphragm','Uvula','Bronchiole','A','The epiglottis folds over the airway during swallowing.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (111,3,'In a food chain, what is the original source of energy for most ecosystems?','The Sun','Soil minerals','Decomposers','Wind','A','Producers capture solar energy and make it available to other trophic levels.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (112,3,'Which process removes metabolic waste products from an organism?','Nutrition','Excretion','Assimilation','Reproduction','B','Excretion removes waste products formed by metabolism.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (113,3,'Which part of the nephron selectively reabsorbs useful substances from the filtrate?','Renal tubule','Ureter','Bladder','Renal pelvis','A','The renal tubule reabsorbs water, glucose, and ions according to the body\'s needs.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (114,3,'Which type of reproduction usually produces offspring genetically similar to one parent?','Sexual reproduction','Asexual reproduction','Cross-pollination','Fertilisation','B','Asexual reproduction involves one parent and usually produces genetically similar offspring.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (115,3,'Which gas is taken in by green plants for photosynthesis?','Oxygen','Carbon dioxide','Nitrogen','Hydrogen','B','Carbon dioxide is a raw material for photosynthesis.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (116,3,'Which type of joint allows movement in many directions at the shoulder?','Hinge joint','Ball-and-socket joint','Pivot joint','Fixed joint','B','The shoulder\'s ball-and-socket joint permits movement through a wide range of directions.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (117,3,'Why are antibiotics ineffective against influenza viruses?','Viruses have no cell-wall structures targeted by many antibiotics','Viruses are larger than bacteria','Viruses contain chlorophyll','Antibiotics only work in cold climates','A','Antibiotics target bacterial structures or processes; viruses reproduce inside host cells.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (118,3,'Which human cell part contains most of the genetic material?','Nucleus','Cell membrane','Ribosome','Lysosome','A','The nucleus contains chromosomes made of DNA in most human cells.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (119,3,'What is the name for the gradual change in inherited characteristics of populations over generations?','Ecological succession','Evolution','Homeostasis','Fermentation','B','Evolution describes inherited population changes across generations.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (120,3,'Which condition is required for seeds to germinate?','Water, oxygen and suitable temperature','Continuous bright light only','Carbon dioxide and salt','Complete submersion in water','A','Most seeds require moisture, oxygen, and a suitable temperature to germinate.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (121,3,'Which organism is a decomposer in a terrestrial ecosystem?','Mushroom','Hawk','Grass','Goat','A','Fungi such as mushrooms break down dead organic material.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (122,3,'What is the main benefit of vaccination to a population?','It can increase immunity and reduce transmission','It replaces all hygiene practices','It treats every disease after symptoms start','It prevents organisms from mutating','A','Vaccination can build immunity and reduce the spread of vaccine-preventable diseases.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (163,16,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (164,16,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (165,16,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (166,16,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (167,16,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (168,16,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (169,16,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (170,16,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (171,16,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (172,16,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (173,16,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (174,16,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (175,16,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (176,16,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (177,16,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (178,16,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (179,16,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (180,16,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (181,16,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (182,16,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (183,16,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (184,16,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (185,16,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (186,16,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (187,16,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (188,16,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (189,16,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (190,16,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (191,16,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (192,16,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (193,16,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (194,16,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (195,16,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (196,16,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (197,16,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (198,16,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (199,16,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (200,16,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (201,16,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (202,16,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (226,17,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (227,17,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (228,17,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (229,17,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (230,17,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (231,17,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (232,17,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (233,17,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (234,17,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (235,17,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (236,17,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (237,17,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (238,17,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (239,17,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (240,17,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (241,17,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (242,17,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (243,17,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (244,17,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (245,17,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (246,17,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (247,17,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (248,17,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (249,17,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (250,17,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (251,17,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (252,17,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (253,17,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (254,17,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (255,17,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (256,17,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (257,17,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (258,17,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (259,17,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (260,17,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (261,17,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (262,17,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (263,17,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (264,17,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (265,17,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (289,18,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (290,18,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (291,18,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (292,18,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (293,18,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (294,18,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (295,18,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (296,18,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (297,18,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (298,18,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (299,18,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (300,18,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (301,18,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (302,18,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (303,18,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (304,18,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (305,18,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (306,18,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (307,18,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (308,18,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (309,18,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (310,18,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (311,18,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (312,18,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (313,18,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (314,18,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (315,18,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (316,18,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (317,18,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (318,18,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (319,18,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (320,18,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (321,18,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (322,18,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (323,18,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (324,18,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (325,18,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (326,18,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (327,18,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (328,18,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (352,20,'Choose the word nearest in meaning to \"concise\".','Brief','Confusing','Detailed','Uncertain','A','Concise means expressed clearly in few words, or brief.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (353,20,'Choose the correct completion: Neither the teacher nor the students ___ ready.','is','was','are','has','C','With neither/nor, the verb agrees with the nearer subject, \"students\".',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (354,20,'Which word is opposite in meaning to \"scarce\"?','Rare','Plentiful','Limited','Uncommon','B','Plentiful means available in large quantities, the opposite of scarce.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (355,20,'Select the correctly punctuated sentence.','After lunch we returned, to class.','After lunch, we returned to class.','After, lunch we returned to class.','After lunch we, returned to class.','B','The introductory phrase is followed by a comma; the subject and verb stay together.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (356,20,'In \"The committee reached a unanimous decision,\" what does \"unanimous\" mean?','Made quickly','Made by everyone in agreement','Made in secret','Made after a debate','B','A unanimous decision is one supported by all members.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (357,20,'Choose the correct word: She has lived in Abuja ___ 2020.','for','since','during','by','B','\"Since\" introduces the starting point of a period that continues to the present.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (358,20,'Which sentence is in the passive voice?','The team solved the problem.','The problem was solved by the team.','The team is solving the problem.','The team will solve the problem.','B','The subject \"problem\" receives the action in \"was solved\".',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (359,20,'Choose the correctly spelt word.','Accomodation','Acommodation','Accommodation','Accommondation','C','The standard spelling is accommodation, with double c and double m.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (360,20,'What is the function of \"although\" in \"Although it rained, the match continued\"?','It introduces a contrast.','It gives a reason.','It states a result.','It gives an example.','A','Although introduces a contrast between the rain and the match continuing.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (361,20,'Choose the correct reported form: Musa said, \"I am tired.\"','Musa said that I am tired.','Musa said that he was tired.','Musa says that he tired.','Musa said he is tiring.','B','In reported speech, the pronoun changes to he and the present tense shifts to past.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (362,20,'Choose the word nearest in meaning to \"diligent\" in the sentence: The diligent student revised every evening.','Careless','Hard-working','Impatient','Uncertain','B','Diligent means showing steady, careful effort.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (363,20,'Choose the word opposite in meaning to \"expand\" as used in: The committee plans to expand the programme.','Enlarge','Extend','Reduce','Develop','C','Reduce is the opposite of expand.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (364,20,'Select the correct completion: Each of the players ___ received a medal.','have','has','are','were','B','The subject \"each\" is singular and takes \"has\".',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (365,20,'Choose the correct completion: The information ___ useful to the new students.','are','were','is','have been','C','Information is an uncountable singular noun and takes \"is\".',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (366,20,'Which sentence uses the apostrophe correctly to show that the books belong to several teachers?','The teachers book are new.','The teacher\'s books are new.','The teachers\' books are new.','The teachers\'s books are new.','C','The plural possessive is formed by placing the apostrophe after the plural noun.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (367,20,'Choose the sentence with correct subject-verb agreement.','The list of items are on the desk.','The list of items is on the desk.','The list of items were on the desk.','The list of items have been on the desk.','B','The head noun is \"list\", which is singular; the phrase \"of items\" does not change it.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (368,20,'In the sentence \"Because the road was flooded, the team arrived late,\" what does the opening clause express?','A contrast','A reason','A comparison','A purpose','B','The flooded road is the reason the team arrived late.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (369,20,'Select the correctly spelt word.','Seperate','Separate','Seperete','Sepparate','B','The standard spelling is separate.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (370,20,'Choose the word that best completes the sentence: The witness gave a ___ account of the event.','reliable','rely','reliably','reliability','A','An adjective is required before the noun \"account\"; \"reliable\" fits.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (371,20,'Choose the correct reported form: \"We will return tomorrow,\" the visitors said.','The visitors said they will return tomorrow.','The visitors said that they would return the next day.','The visitors say they returned tomorrow.','The visitors said that we return the next day.','B','Reported future shifts from will to would, and tomorrow becomes the next day.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (372,20,'Which option is a complete sentence?','Although the rain stopped.','When the bus reached the station.','The candidates waited outside the hall.','After the long examination.','C','This option contains a subject and a complete predicate without a dependent clause.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (373,20,'Choose the correct preposition: The principal congratulated the team ___ its performance.','for','with','at','by','A','The standard collocation is congratulate someone for an achievement.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (374,20,'In \"The evidence was compelling,\" what does \"compelling\" mean?','Difficult to find','Strong and convincing','Unrelated to the claim','Based on a guess','B','Compelling evidence is strong enough to persuade.',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (375,20,'Select the correctly punctuated direct speech.','Amina said \"I have finished\".','Amina said, \"I have finished.\"','Amina said \"I have finished.\",','Amina, said, \"I have finished\".','B','A comma introduces the quotation and the full stop is placed inside the closing quotation mark.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (376,20,'Choose the appropriate conjunction: The class practised daily, ___ its accuracy improved.','so','unless','although','whereas','A','\"So\" introduces the result of practising daily.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (377,20,'Which sentence uses \"fewer\" correctly?','There is fewer water in the tank.','The class made fewer errors this week.','She has fewer patience today.','We need fewer information.','B','Fewer is used with countable plural nouns such as errors.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (378,20,'Choose the correct completion: If Chidi ___ earlier, he would have caught the first bus.','leaves','left','had left','will leave','C','The third conditional uses if + past perfect and would have + past participle.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (379,20,'Choose the correct comparative form of \"careful\".','Carefuller','More careful','Most careful','Carefulest','B','For this multi-syllable adjective, the comparative is \"more careful\".',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (380,20,'What is the function of the semicolon in \"The first trial failed; the second succeeded\"?','It joins two closely related independent clauses.','It introduces a list.','It marks a question.','It replaces an apostrophe.','A','A semicolon can join two independent clauses that are closely connected in meaning.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (381,20,'Choose the word nearest in meaning to \"reluctant\".','Unwilling','Excited','Certain','Carefree','A','Reluctant means hesitant or unwilling.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (382,20,'Select the correct completion: The news ___ spread quickly through the town.','have','has','are','were','B','News is grammatically singular and takes \"has\".',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (383,20,'Which sentence is in the active voice?','The report was prepared by the group.','The group prepared the report.','The report is being prepared.','The report had been prepared.','B','The subject \"group\" performs the action in the active sentence.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (385,20,'Choose the correct completion: The students, together with their tutor, ___ attending the workshop.','is','was','are','has','C','The main subject \"students\" is plural; the intervening phrase does not change agreement.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (386,20,'In \"The manager postponed the meeting because the report was incomplete,\" which clause gives the reason?','The manager postponed the meeting.','The report was incomplete.','The meeting was postponed.','The manager was incomplete.','B','The clause introduced by \"because\" states the reason for postponement.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (387,20,'Choose the appropriate word: The twins were born ___ the same day.','in','on','at','by','B','\"On\" is used with a specific day or date.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (388,20,'Choose the word nearest in meaning to \"obstacle\".','Advantage','Barrier','Reward','Direction','B','An obstacle is something that blocks progress, a barrier.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (389,20,'Which sentence correctly uses \"their\"?','The school changed their timetable.','The students placed their books on the shelf.','Their going to the library now.','The book is over their.','B','\"Their\" is a possessive determiner referring to the students.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (390,20,'Choose the correct completion: No sooner had the bell rung ___ the candidates entered the hall.','when','than','while','then','B','The fixed construction is \"no sooner ... than\".',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (391,20,'Choose the word opposite in meaning to \"transparent\" when describing a decision process.','Clear','Open','Secretive','Simple','C','A secretive process is the opposite of a transparent one.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (415,21,'Which organelle is the main site of aerobic respiration in a cell?','Ribosome','Mitochondrion','Golgi apparatus','Vacuole','B','Mitochondria release energy through aerobic respiration.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (416,21,'Which process produces glucose in green plants?','Transpiration','Respiration','Photosynthesis','Fermentation','C','Photosynthesis uses light energy, carbon dioxide, and water to produce glucose.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (417,21,'What is the basic structural and functional unit of life?','Tissue','Organ','Cell','System','C','The cell is the smallest unit capable of carrying out life processes.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (418,21,'Which blood component transports most oxygen?','Platelets','Red blood cells','Plasma','White blood cells','B','Haemoglobin in red blood cells binds and transports most oxygen.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (419,21,'The transfer of pollen from anther to stigma is called what?','Fertilisation','Pollination','Germination','Dispersal','B','Pollination is the transfer of pollen grains to a flower stigma.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (420,21,'Which organism is a primary consumer in a grassland food chain?','Grass','Grasshopper','Snake','Hawk','B','A grasshopper feeds on producers such as grass, so it is a primary consumer.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (421,21,'Which part of the human kidney filters blood?','Nephron','Alveolus','Neuron','Villus','A','Each nephron filters blood and helps form urine.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (422,21,'What is the term for an organism\'s observable characteristics?','Genotype','Phenotype','Allele','Mutation','B','Phenotype describes observable traits produced by genes and environment.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (423,21,'Which gas is released by plants during photosynthesis?','Nitrogen','Carbon dioxide','Oxygen','Methane','C','Oxygen is released when water molecules are split during photosynthesis.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (424,21,'What is the main role of decomposers in an ecosystem?','Make sunlight','Recycle nutrients','Produce oxygen only','Control rainfall','B','Decomposers break down dead material and return nutrients to the ecosystem.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (425,21,'A plant cell is placed in a concentrated salt solution and loses water. Which process explains the movement of water?','Diffusion','Osmosis','Active transport','Translocation','B','Water moves across a selectively permeable membrane from higher water potential to lower water potential by osmosis.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (426,21,'Which tissue carries water and dissolved mineral salts from roots towards the leaves?','Phloem','Xylem','Epidermis','Cambium','B','Xylem vessels transport water and mineral salts from roots through the plant.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (427,21,'Which organ produces bile, a substance that helps emulsify fats during digestion?','Pancreas','Liver','Stomach','Small intestine','B','The liver produces bile; the gall bladder stores and releases it.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (428,21,'A heterozygous tall plant is crossed with a dwarf plant. If tallness is dominant, what proportion of offspring is expected to be tall?','One quarter','One half','Three quarters','All offspring','B','Tt crossed with tt gives half Tt tall offspring and half tt dwarf offspring.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (429,21,'Which part of a flower receives pollen grains during pollination?','Anther','Stigma','Ovary','Filament','B','The stigma is the receptive surface for pollen grains.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (430,21,'Which process releases energy from glucose in the cells of animals?','Photosynthesis','Respiration','Transpiration','Excretion','B','Cellular respiration releases usable energy from glucose.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (431,21,'Which blood vessel carries blood away from the heart?','Vein','Artery','Capillary','Venule','B','Arteries carry blood away from the heart, irrespective of oxygen content.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (432,21,'A population of insects increases after its main predator becomes scarce. Which ecological relationship has changed?','Predation','Commensalism','Pollination','Parasitism','A','Reduced predation can allow prey numbers to rise.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (433,21,'Which structure in the human respiratory system is the main site of gaseous exchange?','Trachea','Bronchus','Alveolus','Larynx','C','Thin-walled alveoli provide a large surface area for oxygen and carbon dioxide exchange.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (434,21,'Which nutrient is the primary immediate source of energy in a balanced diet?','Carbohydrate','Vitamin','Mineral salt','Water','A','Carbohydrates are commonly broken down to provide energy for cellular activities.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (435,21,'What is the role of chlorophyll in a green leaf?','Absorb light energy','Transport sugars','Store mineral salts','Open the stomata','A','Chlorophyll absorbs light energy used in photosynthesis.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (436,21,'Which plant response causes a shoot to bend towards a source of light?','Geotropism','Phototropism','Hydrotropism','Thigmotropism','B','Phototropism is directional growth in response to light.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (437,21,'Which cells in the pancreas release insulin into the blood?','Beta cells','Red blood cells','Nerve cells','Goblet cells','A','Pancreatic beta cells produce insulin, which helps regulate blood glucose.',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (438,21,'Which feature of a fish helps it maintain balance and control movement in water?','Swim bladder only','Fins','Gill rakers','Scales','B','Fins provide steering, stability, and propulsion.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (439,21,'Which microorganism is commonly used in baking to make dough rise?','Yeast','Amoeba','Plasmodium','Rhizobium','A','Yeast ferments sugars and releases carbon dioxide, which expands dough.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (440,21,'Which term describes animals that maintain a relatively constant internal body temperature?','Ectothermic','Endothermic','Anaerobic','Aquatic','B','Endothermic animals generate and regulate body heat internally.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (441,21,'What is the main function of root hairs in a plant?','Absorb water and mineral ions','Make seeds','Carry sugars to flowers','Prevent pollination','A','Root hairs increase surface area for absorption from the soil.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (442,21,'Which structure prevents food from entering the trachea during swallowing?','Epiglottis','Diaphragm','Uvula','Bronchiole','A','The epiglottis folds over the airway during swallowing.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (443,21,'In a food chain, what is the original source of energy for most ecosystems?','The Sun','Soil minerals','Decomposers','Wind','A','Producers capture solar energy and make it available to other trophic levels.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (444,21,'Which process removes metabolic waste products from an organism?','Nutrition','Excretion','Assimilation','Reproduction','B','Excretion removes waste products formed by metabolism.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (445,21,'Which part of the nephron selectively reabsorbs useful substances from the filtrate?','Renal tubule','Ureter','Bladder','Renal pelvis','A','The renal tubule reabsorbs water, glucose, and ions according to the body\'s needs.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (446,21,'Which type of reproduction usually produces offspring genetically similar to one parent?','Sexual reproduction','Asexual reproduction','Cross-pollination','Fertilisation','B','Asexual reproduction involves one parent and usually produces genetically similar offspring.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (447,21,'Which gas is taken in by green plants for photosynthesis?','Oxygen','Carbon dioxide','Nitrogen','Hydrogen','B','Carbon dioxide is a raw material for photosynthesis.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (448,21,'Which type of joint allows movement in many directions at the shoulder?','Hinge joint','Ball-and-socket joint','Pivot joint','Fixed joint','B','The shoulder\'s ball-and-socket joint permits movement through a wide range of directions.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (449,21,'Why are antibiotics ineffective against influenza viruses?','Viruses have no cell-wall structures targeted by many antibiotics','Viruses are larger than bacteria','Viruses contain chlorophyll','Antibiotics only work in cold climates','A','Antibiotics target bacterial structures or processes; viruses reproduce inside host cells.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (450,21,'Which human cell part contains most of the genetic material?','Nucleus','Cell membrane','Ribosome','Lysosome','A','The nucleus contains chromosomes made of DNA in most human cells.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (451,21,'What is the name for the gradual change in inherited characteristics of populations over generations?','Ecological succession','Evolution','Homeostasis','Fermentation','B','Evolution describes inherited population changes across generations.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (452,21,'Which condition is required for seeds to germinate?','Water, oxygen and suitable temperature','Continuous bright light only','Carbon dioxide and salt','Complete submersion in water','A','Most seeds require moisture, oxygen, and a suitable temperature to germinate.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (453,21,'Which organism is a decomposer in a terrestrial ecosystem?','Mushroom','Hawk','Grass','Goat','A','Fungi such as mushrooms break down dead organic material.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (454,21,'What is the main benefit of vaccination to a population?','It can increase immunity and reduce transmission','It replaces all hygiene practices','It treats every disease after symptoms start','It prevents organisms from mutating','A','Vaccination can build immunity and reduce the spread of vaccine-preventable diseases.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (478,22,'Which organelle is the main site of aerobic respiration in a cell?','Ribosome','Mitochondrion','Golgi apparatus','Vacuole','B','Mitochondria release energy through aerobic respiration.',1.00,1);
