INSERT  IGNORE INTO `cbt_questions` VALUES (541,23,'Choose the word nearest in meaning to \"concise\".','Brief','Confusing','Detailed','Uncertain','A','Concise means expressed clearly in few words, or brief.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (542,23,'Choose the correct completion: Neither the teacher nor the students ___ ready.','is','was','are','has','C','With neither/nor, the verb agrees with the nearer subject, \"students\".',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (543,23,'Which word is opposite in meaning to \"scarce\"?','Rare','Plentiful','Limited','Uncommon','B','Plentiful means available in large quantities, the opposite of scarce.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (544,23,'Select the correctly punctuated sentence.','After lunch we returned, to class.','After lunch, we returned to class.','After, lunch we returned to class.','After lunch we, returned to class.','B','The introductory phrase is followed by a comma; the subject and verb stay together.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (545,23,'In \"The committee reached a unanimous decision,\" what does \"unanimous\" mean?','Made quickly','Made by everyone in agreement','Made in secret','Made after a debate','B','A unanimous decision is one supported by all members.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (546,23,'Choose the correct word: She has lived in Abuja ___ 2020.','for','since','during','by','B','\"Since\" introduces the starting point of a period that continues to the present.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (547,23,'Which sentence is in the passive voice?','The team solved the problem.','The problem was solved by the team.','The team is solving the problem.','The team will solve the problem.','B','The subject \"problem\" receives the action in \"was solved\".',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (548,23,'Choose the correctly spelt word.','Accomodation','Acommodation','Accommodation','Accommondation','C','The standard spelling is accommodation, with double c and double m.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (549,23,'What is the function of \"although\" in \"Although it rained, the match continued\"?','It introduces a contrast.','It gives a reason.','It states a result.','It gives an example.','A','Although introduces a contrast between the rain and the match continuing.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (550,23,'Choose the correct reported form: Musa said, \"I am tired.\"','Musa said that I am tired.','Musa said that he was tired.','Musa says that he tired.','Musa said he is tiring.','B','In reported speech, the pronoun changes to he and the present tense shifts to past.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (551,23,'Choose the word nearest in meaning to \"diligent\" in the sentence: The diligent student revised every evening.','Careless','Hard-working','Impatient','Uncertain','B','Diligent means showing steady, careful effort.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (552,23,'Choose the word opposite in meaning to \"expand\" as used in: The committee plans to expand the programme.','Enlarge','Extend','Reduce','Develop','C','Reduce is the opposite of expand.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (553,23,'Select the correct completion: Each of the players ___ received a medal.','have','has','are','were','B','The subject \"each\" is singular and takes \"has\".',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (554,23,'Choose the correct completion: The information ___ useful to the new students.','are','were','is','have been','C','Information is an uncountable singular noun and takes \"is\".',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (555,23,'Which sentence uses the apostrophe correctly to show that the books belong to several teachers?','The teachers book are new.','The teacher\'s books are new.','The teachers\' books are new.','The teachers\'s books are new.','C','The plural possessive is formed by placing the apostrophe after the plural noun.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (556,23,'Choose the sentence with correct subject-verb agreement.','The list of items are on the desk.','The list of items is on the desk.','The list of items were on the desk.','The list of items have been on the desk.','B','The head noun is \"list\", which is singular; the phrase \"of items\" does not change it.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (557,23,'In the sentence \"Because the road was flooded, the team arrived late,\" what does the opening clause express?','A contrast','A reason','A comparison','A purpose','B','The flooded road is the reason the team arrived late.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (558,23,'Select the correctly spelt word.','Seperate','Separate','Seperete','Sepparate','B','The standard spelling is separate.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (559,23,'Choose the word that best completes the sentence: The witness gave a ___ account of the event.','reliable','rely','reliably','reliability','A','An adjective is required before the noun \"account\"; \"reliable\" fits.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (560,23,'Choose the correct reported form: \"We will return tomorrow,\" the visitors said.','The visitors said they will return tomorrow.','The visitors said that they would return the next day.','The visitors say they returned tomorrow.','The visitors said that we return the next day.','B','Reported future shifts from will to would, and tomorrow becomes the next day.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (561,23,'Which option is a complete sentence?','Although the rain stopped.','When the bus reached the station.','The candidates waited outside the hall.','After the long examination.','C','This option contains a subject and a complete predicate without a dependent clause.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (562,23,'Choose the correct preposition: The principal congratulated the team ___ its performance.','for','with','at','by','A','The standard collocation is congratulate someone for an achievement.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (563,23,'In \"The evidence was compelling,\" what does \"compelling\" mean?','Difficult to find','Strong and convincing','Unrelated to the claim','Based on a guess','B','Compelling evidence is strong enough to persuade.',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (564,23,'Select the correctly punctuated direct speech.','Amina said \"I have finished\".','Amina said, \"I have finished.\"','Amina said \"I have finished.\",','Amina, said, \"I have finished\".','B','A comma introduces the quotation and the full stop is placed inside the closing quotation mark.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (565,23,'Choose the appropriate conjunction: The class practised daily, ___ its accuracy improved.','so','unless','although','whereas','A','\"So\" introduces the result of practising daily.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (566,23,'Which sentence uses \"fewer\" correctly?','There is fewer water in the tank.','The class made fewer errors this week.','She has fewer patience today.','We need fewer information.','B','Fewer is used with countable plural nouns such as errors.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (567,23,'Choose the correct completion: If Chidi ___ earlier, he would have caught the first bus.','leaves','left','had left','will leave','C','The third conditional uses if + past perfect and would have + past participle.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (568,23,'Choose the correct comparative form of \"careful\".','Carefuller','More careful','Most careful','Carefulest','B','For this multi-syllable adjective, the comparative is \"more careful\".',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (569,23,'What is the function of the semicolon in \"The first trial failed; the second succeeded\"?','It joins two closely related independent clauses.','It introduces a list.','It marks a question.','It replaces an apostrophe.','A','A semicolon can join two independent clauses that are closely connected in meaning.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (570,23,'Choose the word nearest in meaning to \"reluctant\".','Unwilling','Excited','Certain','Carefree','A','Reluctant means hesitant or unwilling.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (571,23,'Select the correct completion: The news ___ spread quickly through the town.','have','has','are','were','B','News is grammatically singular and takes \"has\".',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (572,23,'Which sentence is in the active voice?','The report was prepared by the group.','The group prepared the report.','The report is being prepared.','The report had been prepared.','B','The subject \"group\" performs the action in the active sentence.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (574,23,'Choose the correct completion: The students, together with their tutor, ___ attending the workshop.','is','was','are','has','C','The main subject \"students\" is plural; the intervening phrase does not change agreement.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (575,23,'In \"The manager postponed the meeting because the report was incomplete,\" which clause gives the reason?','The manager postponed the meeting.','The report was incomplete.','The meeting was postponed.','The manager was incomplete.','B','The clause introduced by \"because\" states the reason for postponement.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (576,23,'Choose the appropriate word: The twins were born ___ the same day.','in','on','at','by','B','\"On\" is used with a specific day or date.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (577,23,'Choose the word nearest in meaning to \"obstacle\".','Advantage','Barrier','Reward','Direction','B','An obstacle is something that blocks progress, a barrier.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (578,23,'Which sentence correctly uses \"their\"?','The school changed their timetable.','The students placed their books on the shelf.','Their going to the library now.','The book is over their.','B','\"Their\" is a possessive determiner referring to the students.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (579,23,'Choose the correct completion: No sooner had the bell rung ___ the candidates entered the hall.','when','than','while','then','B','The fixed construction is \"no sooner ... than\".',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (580,23,'Choose the word opposite in meaning to \"transparent\" when describing a decision process.','Clear','Open','Secretive','Simple','C','A secretive process is the opposite of a transparent one.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (604,24,'Choose the word nearest in meaning to \"concise\".','Brief','Confusing','Detailed','Uncertain','A','Concise means expressed clearly in few words, or brief.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (605,24,'Choose the correct completion: Neither the teacher nor the students ___ ready.','is','was','are','has','C','With neither/nor, the verb agrees with the nearer subject, \"students\".',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (606,24,'Which word is opposite in meaning to \"scarce\"?','Rare','Plentiful','Limited','Uncommon','B','Plentiful means available in large quantities, the opposite of scarce.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (607,24,'Select the correctly punctuated sentence.','After lunch we returned, to class.','After lunch, we returned to class.','After, lunch we returned to class.','After lunch we, returned to class.','B','The introductory phrase is followed by a comma; the subject and verb stay together.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (608,24,'In \"The committee reached a unanimous decision,\" what does \"unanimous\" mean?','Made quickly','Made by everyone in agreement','Made in secret','Made after a debate','B','A unanimous decision is one supported by all members.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (609,24,'Choose the correct word: She has lived in Abuja ___ 2020.','for','since','during','by','B','\"Since\" introduces the starting point of a period that continues to the present.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (610,24,'Which sentence is in the passive voice?','The team solved the problem.','The problem was solved by the team.','The team is solving the problem.','The team will solve the problem.','B','The subject \"problem\" receives the action in \"was solved\".',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (611,24,'Choose the correctly spelt word.','Accomodation','Acommodation','Accommodation','Accommondation','C','The standard spelling is accommodation, with double c and double m.',1.00,8);
