INSERT  IGNORE INTO `cbt_questions` VALUES (637,24,'Choose the correct completion: The students, together with their tutor, ___ attending the workshop.','is','was','are','has','C','The main subject \"students\" is plural; the intervening phrase does not change agreement.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (638,24,'In \"The manager postponed the meeting because the report was incomplete,\" which clause gives the reason?','The manager postponed the meeting.','The report was incomplete.','The meeting was postponed.','The manager was incomplete.','B','The clause introduced by \"because\" states the reason for postponement.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (639,24,'Choose the appropriate word: The twins were born ___ the same day.','in','on','at','by','B','\"On\" is used with a specific day or date.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (640,24,'Choose the word nearest in meaning to \"obstacle\".','Advantage','Barrier','Reward','Direction','B','An obstacle is something that blocks progress, a barrier.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (641,24,'Which sentence correctly uses \"their\"?','The school changed their timetable.','The students placed their books on the shelf.','Their going to the library now.','The book is over their.','B','\"Their\" is a possessive determiner referring to the students.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (642,24,'Choose the correct completion: No sooner had the bell rung ___ the candidates entered the hall.','when','than','while','then','B','The fixed construction is \"no sooner ... than\".',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (643,24,'Choose the word opposite in meaning to \"transparent\" when describing a decision process.','Clear','Open','Secretive','Simple','C','A secretive process is the opposite of a transparent one.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (667,25,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (668,25,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (669,25,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (670,25,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (671,25,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (672,25,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (673,25,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (674,25,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (675,25,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (676,25,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (677,25,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (678,25,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (679,25,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (680,25,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (681,25,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (682,25,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (683,25,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (684,25,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (685,25,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (686,25,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (687,25,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (688,25,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (689,25,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (690,25,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (691,25,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (692,25,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (693,25,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (694,25,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (695,25,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (696,25,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (697,25,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (698,25,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (699,25,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (700,25,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (701,25,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (702,25,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (703,25,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (704,25,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (705,25,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (706,25,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (730,26,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (731,26,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (732,26,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (733,26,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (734,26,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (735,26,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (736,26,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (737,26,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (738,26,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (739,26,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (740,26,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (741,26,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (742,26,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (743,26,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (744,26,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (745,26,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (746,26,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (747,26,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (748,26,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (749,26,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (750,26,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (751,26,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (752,26,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (753,26,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (754,26,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (755,26,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (756,26,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (757,26,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (758,26,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (759,26,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (760,26,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (761,26,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (762,26,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (763,26,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (764,26,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (765,26,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (766,26,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (767,26,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (768,26,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (769,26,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (793,28,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (794,28,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (795,28,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (796,28,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (797,28,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (798,28,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (799,28,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (800,28,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (801,28,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (802,28,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (803,28,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (804,28,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (805,28,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (806,28,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (807,28,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (808,28,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (809,28,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (810,28,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (811,28,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (812,28,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (813,28,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (814,28,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (815,28,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (816,28,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (817,28,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (818,28,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (819,28,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (820,28,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (821,28,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
