INSERT  IGNORE INTO `cbt_questions` VALUES (1184,35,'A heterozygous tall plant is crossed with a dwarf plant. If tallness is dominant, what proportion of offspring is expected to be tall?','One quarter','One half','Three quarters','All offspring','B','Tt crossed with tt gives half Tt tall offspring and half tt dwarf offspring.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1185,35,'Which part of a flower receives pollen grains during pollination?','Anther','Stigma','Ovary','Filament','B','The stigma is the receptive surface for pollen grains.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1186,35,'Which process releases energy from glucose in the cells of animals?','Photosynthesis','Respiration','Transpiration','Excretion','B','Cellular respiration releases usable energy from glucose.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1187,35,'Which blood vessel carries blood away from the heart?','Vein','Artery','Capillary','Venule','B','Arteries carry blood away from the heart, irrespective of oxygen content.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1188,35,'A population of insects increases after its main predator becomes scarce. Which ecological relationship has changed?','Predation','Commensalism','Pollination','Parasitism','A','Reduced predation can allow prey numbers to rise.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1189,35,'Which structure in the human respiratory system is the main site of gaseous exchange?','Trachea','Bronchus','Alveolus','Larynx','C','Thin-walled alveoli provide a large surface area for oxygen and carbon dioxide exchange.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1190,35,'Which nutrient is the primary immediate source of energy in a balanced diet?','Carbohydrate','Vitamin','Mineral salt','Water','A','Carbohydrates are commonly broken down to provide energy for cellular activities.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1191,35,'What is the role of chlorophyll in a green leaf?','Absorb light energy','Transport sugars','Store mineral salts','Open the stomata','A','Chlorophyll absorbs light energy used in photosynthesis.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1192,35,'Which plant response causes a shoot to bend towards a source of light?','Geotropism','Phototropism','Hydrotropism','Thigmotropism','B','Phototropism is directional growth in response to light.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1193,35,'Which cells in the pancreas release insulin into the blood?','Beta cells','Red blood cells','Nerve cells','Goblet cells','A','Pancreatic beta cells produce insulin, which helps regulate blood glucose.',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1194,35,'Which feature of a fish helps it maintain balance and control movement in water?','Swim bladder only','Fins','Gill rakers','Scales','B','Fins provide steering, stability, and propulsion.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1195,35,'Which microorganism is commonly used in baking to make dough rise?','Yeast','Amoeba','Plasmodium','Rhizobium','A','Yeast ferments sugars and releases carbon dioxide, which expands dough.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1196,35,'Which term describes animals that maintain a relatively constant internal body temperature?','Ectothermic','Endothermic','Anaerobic','Aquatic','B','Endothermic animals generate and regulate body heat internally.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1197,35,'What is the main function of root hairs in a plant?','Absorb water and mineral ions','Make seeds','Carry sugars to flowers','Prevent pollination','A','Root hairs increase surface area for absorption from the soil.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1198,35,'Which structure prevents food from entering the trachea during swallowing?','Epiglottis','Diaphragm','Uvula','Bronchiole','A','The epiglottis folds over the airway during swallowing.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1199,35,'In a food chain, what is the original source of energy for most ecosystems?','The Sun','Soil minerals','Decomposers','Wind','A','Producers capture solar energy and make it available to other trophic levels.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1200,35,'Which process removes metabolic waste products from an organism?','Nutrition','Excretion','Assimilation','Reproduction','B','Excretion removes waste products formed by metabolism.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1201,35,'Which part of the nephron selectively reabsorbs useful substances from the filtrate?','Renal tubule','Ureter','Bladder','Renal pelvis','A','The renal tubule reabsorbs water, glucose, and ions according to the body\'s needs.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1202,35,'Which type of reproduction usually produces offspring genetically similar to one parent?','Sexual reproduction','Asexual reproduction','Cross-pollination','Fertilisation','B','Asexual reproduction involves one parent and usually produces genetically similar offspring.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1203,35,'Which gas is taken in by green plants for photosynthesis?','Oxygen','Carbon dioxide','Nitrogen','Hydrogen','B','Carbon dioxide is a raw material for photosynthesis.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1204,35,'Which type of joint allows movement in many directions at the shoulder?','Hinge joint','Ball-and-socket joint','Pivot joint','Fixed joint','B','The shoulder\'s ball-and-socket joint permits movement through a wide range of directions.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1205,35,'Why are antibiotics ineffective against influenza viruses?','Viruses have no cell-wall structures targeted by many antibiotics','Viruses are larger than bacteria','Viruses contain chlorophyll','Antibiotics only work in cold climates','A','Antibiotics target bacterial structures or processes; viruses reproduce inside host cells.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1206,35,'Which human cell part contains most of the genetic material?','Nucleus','Cell membrane','Ribosome','Lysosome','A','The nucleus contains chromosomes made of DNA in most human cells.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1207,35,'What is the name for the gradual change in inherited characteristics of populations over generations?','Ecological succession','Evolution','Homeostasis','Fermentation','B','Evolution describes inherited population changes across generations.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1208,35,'Which condition is required for seeds to germinate?','Water, oxygen and suitable temperature','Continuous bright light only','Carbon dioxide and salt','Complete submersion in water','A','Most seeds require moisture, oxygen, and a suitable temperature to germinate.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1209,35,'Which organism is a decomposer in a terrestrial ecosystem?','Mushroom','Hawk','Grass','Goat','A','Fungi such as mushrooms break down dead organic material.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1210,35,'What is the main benefit of vaccination to a population?','It can increase immunity and reduce transmission','It replaces all hygiene practices','It treats every disease after symptoms start','It prevents organisms from mutating','A','Vaccination can build immunity and reduce the spread of vaccine-preventable diseases.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1234,36,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1235,36,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1236,36,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1237,36,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1238,36,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1239,36,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1240,36,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1241,36,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1242,36,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1243,36,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1244,36,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1245,36,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1246,36,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1247,36,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1248,36,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1249,36,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1250,36,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1251,36,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1252,36,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1253,36,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1254,36,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1255,36,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1256,36,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1257,36,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1258,36,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1259,36,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1260,36,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1261,36,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1262,36,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1263,36,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1264,36,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1265,36,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1266,36,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1267,36,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1268,36,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1269,36,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1270,36,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1271,36,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1272,36,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1273,36,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1297,37,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1298,37,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1299,37,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1300,37,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1301,37,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1302,37,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1303,37,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1304,37,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1305,37,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1306,37,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1307,37,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1308,37,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1309,37,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1310,37,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1311,37,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1312,37,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1313,37,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1314,37,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1315,37,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1316,37,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1317,37,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1318,37,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1319,37,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1320,37,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1321,37,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1322,37,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1323,37,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1324,37,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1325,37,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1326,37,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1327,37,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1328,37,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1329,37,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1330,37,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1331,37,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1332,37,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1333,37,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1334,37,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1335,37,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1336,37,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1360,38,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1361,38,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1362,38,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1363,38,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1364,38,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1365,38,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1366,38,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1367,38,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1368,38,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1369,38,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1370,38,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1371,38,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1372,38,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1373,38,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1374,38,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1375,38,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1376,38,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1377,38,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1378,38,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1379,38,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1380,38,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1381,38,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1382,38,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1383,38,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1384,38,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1385,38,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1386,38,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1387,38,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1388,38,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1389,38,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1390,38,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1391,38,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1392,38,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1393,38,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1394,38,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1395,38,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1396,38,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1397,38,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1398,38,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1399,38,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1423,39,'Which organelle is the main site of aerobic respiration in a cell?','Ribosome','Mitochondrion','Golgi apparatus','Vacuole','B','Mitochondria release energy through aerobic respiration.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1424,39,'Which process produces glucose in green plants?','Transpiration','Respiration','Photosynthesis','Fermentation','C','Photosynthesis uses light energy, carbon dioxide, and water to produce glucose.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1425,39,'What is the basic structural and functional unit of life?','Tissue','Organ','Cell','System','C','The cell is the smallest unit capable of carrying out life processes.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1426,39,'Which blood component transports most oxygen?','Platelets','Red blood cells','Plasma','White blood cells','B','Haemoglobin in red blood cells binds and transports most oxygen.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1427,39,'The transfer of pollen from anther to stigma is called what?','Fertilisation','Pollination','Germination','Dispersal','B','Pollination is the transfer of pollen grains to a flower stigma.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1428,39,'Which organism is a primary consumer in a grassland food chain?','Grass','Grasshopper','Snake','Hawk','B','A grasshopper feeds on producers such as grass, so it is a primary consumer.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1429,39,'Which part of the human kidney filters blood?','Nephron','Alveolus','Neuron','Villus','A','Each nephron filters blood and helps form urine.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1430,39,'What is the term for an organism\'s observable characteristics?','Genotype','Phenotype','Allele','Mutation','B','Phenotype describes observable traits produced by genes and environment.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1431,39,'Which gas is released by plants during photosynthesis?','Nitrogen','Carbon dioxide','Oxygen','Methane','C','Oxygen is released when water molecules are split during photosynthesis.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1432,39,'What is the main role of decomposers in an ecosystem?','Make sunlight','Recycle nutrients','Produce oxygen only','Control rainfall','B','Decomposers break down dead material and return nutrients to the ecosystem.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1433,39,'A plant cell is placed in a concentrated salt solution and loses water. Which process explains the movement of water?','Diffusion','Osmosis','Active transport','Translocation','B','Water moves across a selectively permeable membrane from higher water potential to lower water potential by osmosis.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1434,39,'Which tissue carries water and dissolved mineral salts from roots towards the leaves?','Phloem','Xylem','Epidermis','Cambium','B','Xylem vessels transport water and mineral salts from roots through the plant.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1435,39,'Which organ produces bile, a substance that helps emulsify fats during digestion?','Pancreas','Liver','Stomach','Small intestine','B','The liver produces bile; the gall bladder stores and releases it.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1436,39,'A heterozygous tall plant is crossed with a dwarf plant. If tallness is dominant, what proportion of offspring is expected to be tall?','One quarter','One half','Three quarters','All offspring','B','Tt crossed with tt gives half Tt tall offspring and half tt dwarf offspring.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1437,39,'Which part of a flower receives pollen grains during pollination?','Anther','Stigma','Ovary','Filament','B','The stigma is the receptive surface for pollen grains.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1438,39,'Which process releases energy from glucose in the cells of animals?','Photosynthesis','Respiration','Transpiration','Excretion','B','Cellular respiration releases usable energy from glucose.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1439,39,'Which blood vessel carries blood away from the heart?','Vein','Artery','Capillary','Venule','B','Arteries carry blood away from the heart, irrespective of oxygen content.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1440,39,'A population of insects increases after its main predator becomes scarce. Which ecological relationship has changed?','Predation','Commensalism','Pollination','Parasitism','A','Reduced predation can allow prey numbers to rise.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1441,39,'Which structure in the human respiratory system is the main site of gaseous exchange?','Trachea','Bronchus','Alveolus','Larynx','C','Thin-walled alveoli provide a large surface area for oxygen and carbon dioxide exchange.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1442,39,'Which nutrient is the primary immediate source of energy in a balanced diet?','Carbohydrate','Vitamin','Mineral salt','Water','A','Carbohydrates are commonly broken down to provide energy for cellular activities.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1443,39,'What is the role of chlorophyll in a green leaf?','Absorb light energy','Transport sugars','Store mineral salts','Open the stomata','A','Chlorophyll absorbs light energy used in photosynthesis.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1444,39,'Which plant response causes a shoot to bend towards a source of light?','Geotropism','Phototropism','Hydrotropism','Thigmotropism','B','Phototropism is directional growth in response to light.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1445,39,'Which cells in the pancreas release insulin into the blood?','Beta cells','Red blood cells','Nerve cells','Goblet cells','A','Pancreatic beta cells produce insulin, which helps regulate blood glucose.',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1446,39,'Which feature of a fish helps it maintain balance and control movement in water?','Swim bladder only','Fins','Gill rakers','Scales','B','Fins provide steering, stability, and propulsion.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1447,39,'Which microorganism is commonly used in baking to make dough rise?','Yeast','Amoeba','Plasmodium','Rhizobium','A','Yeast ferments sugars and releases carbon dioxide, which expands dough.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1448,39,'Which term describes animals that maintain a relatively constant internal body temperature?','Ectothermic','Endothermic','Anaerobic','Aquatic','B','Endothermic animals generate and regulate body heat internally.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1449,39,'What is the main function of root hairs in a plant?','Absorb water and mineral ions','Make seeds','Carry sugars to flowers','Prevent pollination','A','Root hairs increase surface area for absorption from the soil.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1450,39,'Which structure prevents food from entering the trachea during swallowing?','Epiglottis','Diaphragm','Uvula','Bronchiole','A','The epiglottis folds over the airway during swallowing.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1451,39,'In a food chain, what is the original source of energy for most ecosystems?','The Sun','Soil minerals','Decomposers','Wind','A','Producers capture solar energy and make it available to other trophic levels.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1452,39,'Which process removes metabolic waste products from an organism?','Nutrition','Excretion','Assimilation','Reproduction','B','Excretion removes waste products formed by metabolism.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1453,39,'Which part of the nephron selectively reabsorbs useful substances from the filtrate?','Renal tubule','Ureter','Bladder','Renal pelvis','A','The renal tubule reabsorbs water, glucose, and ions according to the body\'s needs.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1454,39,'Which type of reproduction usually produces offspring genetically similar to one parent?','Sexual reproduction','Asexual reproduction','Cross-pollination','Fertilisation','B','Asexual reproduction involves one parent and usually produces genetically similar offspring.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1455,39,'Which gas is taken in by green plants for photosynthesis?','Oxygen','Carbon dioxide','Nitrogen','Hydrogen','B','Carbon dioxide is a raw material for photosynthesis.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1456,39,'Which type of joint allows movement in many directions at the shoulder?','Hinge joint','Ball-and-socket joint','Pivot joint','Fixed joint','B','The shoulder\'s ball-and-socket joint permits movement through a wide range of directions.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1457,39,'Why are antibiotics ineffective against influenza viruses?','Viruses have no cell-wall structures targeted by many antibiotics','Viruses are larger than bacteria','Viruses contain chlorophyll','Antibiotics only work in cold climates','A','Antibiotics target bacterial structures or processes; viruses reproduce inside host cells.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1458,39,'Which human cell part contains most of the genetic material?','Nucleus','Cell membrane','Ribosome','Lysosome','A','The nucleus contains chromosomes made of DNA in most human cells.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1459,39,'What is the name for the gradual change in inherited characteristics of populations over generations?','Ecological succession','Evolution','Homeostasis','Fermentation','B','Evolution describes inherited population changes across generations.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1460,39,'Which condition is required for seeds to germinate?','Water, oxygen and suitable temperature','Continuous bright light only','Carbon dioxide and salt','Complete submersion in water','A','Most seeds require moisture, oxygen, and a suitable temperature to germinate.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1461,39,'Which organism is a decomposer in a terrestrial ecosystem?','Mushroom','Hawk','Grass','Goat','A','Fungi such as mushrooms break down dead organic material.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1462,39,'What is the main benefit of vaccination to a population?','It can increase immunity and reduce transmission','It replaces all hygiene practices','It treats every disease after symptoms start','It prevents organisms from mutating','A','Vaccination can build immunity and reduce the spread of vaccine-preventable diseases.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1486,40,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1487,40,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1488,40,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1489,40,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1490,40,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1491,40,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1492,40,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1493,40,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1494,40,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1495,40,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1496,40,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1497,40,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1498,40,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1499,40,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1500,40,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1501,40,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1502,40,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1503,40,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1504,40,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1505,40,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1506,40,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1507,40,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1508,40,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1509,40,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1510,40,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1511,40,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1512,40,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1513,40,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1514,40,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1515,40,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1516,40,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1517,40,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1518,40,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1519,40,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1520,40,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1521,40,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1522,40,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1523,40,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1524,40,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1525,40,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1549,41,'Which organelle is the main site of aerobic respiration in a cell?','Ribosome','Mitochondrion','Golgi apparatus','Vacuole','B','Mitochondria release energy through aerobic respiration.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1550,41,'Which process produces glucose in green plants?','Transpiration','Respiration','Photosynthesis','Fermentation','C','Photosynthesis uses light energy, carbon dioxide, and water to produce glucose.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1551,41,'What is the basic structural and functional unit of life?','Tissue','Organ','Cell','System','C','The cell is the smallest unit capable of carrying out life processes.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1552,41,'Which blood component transports most oxygen?','Platelets','Red blood cells','Plasma','White blood cells','B','Haemoglobin in red blood cells binds and transports most oxygen.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1553,41,'The transfer of pollen from anther to stigma is called what?','Fertilisation','Pollination','Germination','Dispersal','B','Pollination is the transfer of pollen grains to a flower stigma.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1554,41,'Which organism is a primary consumer in a grassland food chain?','Grass','Grasshopper','Snake','Hawk','B','A grasshopper feeds on producers such as grass, so it is a primary consumer.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1555,41,'Which part of the human kidney filters blood?','Nephron','Alveolus','Neuron','Villus','A','Each nephron filters blood and helps form urine.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1556,41,'What is the term for an organism\'s observable characteristics?','Genotype','Phenotype','Allele','Mutation','B','Phenotype describes observable traits produced by genes and environment.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1557,41,'Which gas is released by plants during photosynthesis?','Nitrogen','Carbon dioxide','Oxygen','Methane','C','Oxygen is released when water molecules are split during photosynthesis.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1558,41,'What is the main role of decomposers in an ecosystem?','Make sunlight','Recycle nutrients','Produce oxygen only','Control rainfall','B','Decomposers break down dead material and return nutrients to the ecosystem.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1559,41,'A plant cell is placed in a concentrated salt solution and loses water. Which process explains the movement of water?','Diffusion','Osmosis','Active transport','Translocation','B','Water moves across a selectively permeable membrane from higher water potential to lower water potential by osmosis.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1560,41,'Which tissue carries water and dissolved mineral salts from roots towards the leaves?','Phloem','Xylem','Epidermis','Cambium','B','Xylem vessels transport water and mineral salts from roots through the plant.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1561,41,'Which organ produces bile, a substance that helps emulsify fats during digestion?','Pancreas','Liver','Stomach','Small intestine','B','The liver produces bile; the gall bladder stores and releases it.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1562,41,'A heterozygous tall plant is crossed with a dwarf plant. If tallness is dominant, what proportion of offspring is expected to be tall?','One quarter','One half','Three quarters','All offspring','B','Tt crossed with tt gives half Tt tall offspring and half tt dwarf offspring.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1563,41,'Which part of a flower receives pollen grains during pollination?','Anther','Stigma','Ovary','Filament','B','The stigma is the receptive surface for pollen grains.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1564,41,'Which process releases energy from glucose in the cells of animals?','Photosynthesis','Respiration','Transpiration','Excretion','B','Cellular respiration releases usable energy from glucose.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1565,41,'Which blood vessel carries blood away from the heart?','Vein','Artery','Capillary','Venule','B','Arteries carry blood away from the heart, irrespective of oxygen content.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1566,41,'A population of insects increases after its main predator becomes scarce. Which ecological relationship has changed?','Predation','Commensalism','Pollination','Parasitism','A','Reduced predation can allow prey numbers to rise.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1567,41,'Which structure in the human respiratory system is the main site of gaseous exchange?','Trachea','Bronchus','Alveolus','Larynx','C','Thin-walled alveoli provide a large surface area for oxygen and carbon dioxide exchange.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1568,41,'Which nutrient is the primary immediate source of energy in a balanced diet?','Carbohydrate','Vitamin','Mineral salt','Water','A','Carbohydrates are commonly broken down to provide energy for cellular activities.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1569,41,'What is the role of chlorophyll in a green leaf?','Absorb light energy','Transport sugars','Store mineral salts','Open the stomata','A','Chlorophyll absorbs light energy used in photosynthesis.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1570,41,'Which plant response causes a shoot to bend towards a source of light?','Geotropism','Phototropism','Hydrotropism','Thigmotropism','B','Phototropism is directional growth in response to light.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1571,41,'Which cells in the pancreas release insulin into the blood?','Beta cells','Red blood cells','Nerve cells','Goblet cells','A','Pancreatic beta cells produce insulin, which helps regulate blood glucose.',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1572,41,'Which feature of a fish helps it maintain balance and control movement in water?','Swim bladder only','Fins','Gill rakers','Scales','B','Fins provide steering, stability, and propulsion.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1573,41,'Which microorganism is commonly used in baking to make dough rise?','Yeast','Amoeba','Plasmodium','Rhizobium','A','Yeast ferments sugars and releases carbon dioxide, which expands dough.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1574,41,'Which term describes animals that maintain a relatively constant internal body temperature?','Ectothermic','Endothermic','Anaerobic','Aquatic','B','Endothermic animals generate and regulate body heat internally.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1575,41,'What is the main function of root hairs in a plant?','Absorb water and mineral ions','Make seeds','Carry sugars to flowers','Prevent pollination','A','Root hairs increase surface area for absorption from the soil.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1576,41,'Which structure prevents food from entering the trachea during swallowing?','Epiglottis','Diaphragm','Uvula','Bronchiole','A','The epiglottis folds over the airway during swallowing.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1577,41,'In a food chain, what is the original source of energy for most ecosystems?','The Sun','Soil minerals','Decomposers','Wind','A','Producers capture solar energy and make it available to other trophic levels.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1578,41,'Which process removes metabolic waste products from an organism?','Nutrition','Excretion','Assimilation','Reproduction','B','Excretion removes waste products formed by metabolism.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1579,41,'Which part of the nephron selectively reabsorbs useful substances from the filtrate?','Renal tubule','Ureter','Bladder','Renal pelvis','A','The renal tubule reabsorbs water, glucose, and ions according to the body\'s needs.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1580,41,'Which type of reproduction usually produces offspring genetically similar to one parent?','Sexual reproduction','Asexual reproduction','Cross-pollination','Fertilisation','B','Asexual reproduction involves one parent and usually produces genetically similar offspring.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1581,41,'Which gas is taken in by green plants for photosynthesis?','Oxygen','Carbon dioxide','Nitrogen','Hydrogen','B','Carbon dioxide is a raw material for photosynthesis.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1582,41,'Which type of joint allows movement in many directions at the shoulder?','Hinge joint','Ball-and-socket joint','Pivot joint','Fixed joint','B','The shoulder\'s ball-and-socket joint permits movement through a wide range of directions.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1583,41,'Why are antibiotics ineffective against influenza viruses?','Viruses have no cell-wall structures targeted by many antibiotics','Viruses are larger than bacteria','Viruses contain chlorophyll','Antibiotics only work in cold climates','A','Antibiotics target bacterial structures or processes; viruses reproduce inside host cells.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1584,41,'Which human cell part contains most of the genetic material?','Nucleus','Cell membrane','Ribosome','Lysosome','A','The nucleus contains chromosomes made of DNA in most human cells.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1585,41,'What is the name for the gradual change in inherited characteristics of populations over generations?','Ecological succession','Evolution','Homeostasis','Fermentation','B','Evolution describes inherited population changes across generations.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1586,41,'Which condition is required for seeds to germinate?','Water, oxygen and suitable temperature','Continuous bright light only','Carbon dioxide and salt','Complete submersion in water','A','Most seeds require moisture, oxygen, and a suitable temperature to germinate.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1587,41,'Which organism is a decomposer in a terrestrial ecosystem?','Mushroom','Hawk','Grass','Goat','A','Fungi such as mushrooms break down dead organic material.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1588,41,'What is the main benefit of vaccination to a population?','It can increase immunity and reduce transmission','It replaces all hygiene practices','It treats every disease after symptoms start','It prevents organisms from mutating','A','Vaccination can build immunity and reduce the spread of vaccine-preventable diseases.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1612,42,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1613,42,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1614,42,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1615,42,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1616,42,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1617,42,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1618,42,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1619,42,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1620,42,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1621,42,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1622,42,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1623,42,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1624,42,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1625,42,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1626,42,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1627,42,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1628,42,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1629,42,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1630,42,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1631,42,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1632,42,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1633,42,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1634,42,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1635,42,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1636,42,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1637,42,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1638,42,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1639,42,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1640,42,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1641,42,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1642,42,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1643,42,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1644,42,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1645,42,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1646,42,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1647,42,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1648,42,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1649,42,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1650,42,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1651,42,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1675,43,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1676,43,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1677,43,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1678,43,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1679,43,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1680,43,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1681,43,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1682,43,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1683,43,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1684,43,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1685,43,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1686,43,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1687,43,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1688,43,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1689,43,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1690,43,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1691,43,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1692,43,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1693,43,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1694,43,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1695,43,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1696,43,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1697,43,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1698,43,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1699,43,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1700,43,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1701,43,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1702,43,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1703,43,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1704,43,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
