INSERT  IGNORE INTO `cbt_questions` VALUES (1801,45,'Which organelle is the main site of aerobic respiration in a cell?','Ribosome','Mitochondrion','Golgi apparatus','Vacuole','B','Mitochondria release energy through aerobic respiration.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1802,45,'Which process produces glucose in green plants?','Transpiration','Respiration','Photosynthesis','Fermentation','C','Photosynthesis uses light energy, carbon dioxide, and water to produce glucose.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1803,45,'What is the basic structural and functional unit of life?','Tissue','Organ','Cell','System','C','The cell is the smallest unit capable of carrying out life processes.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1804,45,'Which blood component transports most oxygen?','Platelets','Red blood cells','Plasma','White blood cells','B','Haemoglobin in red blood cells binds and transports most oxygen.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1805,45,'The transfer of pollen from anther to stigma is called what?','Fertilisation','Pollination','Germination','Dispersal','B','Pollination is the transfer of pollen grains to a flower stigma.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1806,45,'Which organism is a primary consumer in a grassland food chain?','Grass','Grasshopper','Snake','Hawk','B','A grasshopper feeds on producers such as grass, so it is a primary consumer.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1807,45,'Which part of the human kidney filters blood?','Nephron','Alveolus','Neuron','Villus','A','Each nephron filters blood and helps form urine.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1808,45,'What is the term for an organism\'s observable characteristics?','Genotype','Phenotype','Allele','Mutation','B','Phenotype describes observable traits produced by genes and environment.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1809,45,'Which gas is released by plants during photosynthesis?','Nitrogen','Carbon dioxide','Oxygen','Methane','C','Oxygen is released when water molecules are split during photosynthesis.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1810,45,'What is the main role of decomposers in an ecosystem?','Make sunlight','Recycle nutrients','Produce oxygen only','Control rainfall','B','Decomposers break down dead material and return nutrients to the ecosystem.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1811,45,'A plant cell is placed in a concentrated salt solution and loses water. Which process explains the movement of water?','Diffusion','Osmosis','Active transport','Translocation','B','Water moves across a selectively permeable membrane from higher water potential to lower water potential by osmosis.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1812,45,'Which tissue carries water and dissolved mineral salts from roots towards the leaves?','Phloem','Xylem','Epidermis','Cambium','B','Xylem vessels transport water and mineral salts from roots through the plant.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1813,45,'Which organ produces bile, a substance that helps emulsify fats during digestion?','Pancreas','Liver','Stomach','Small intestine','B','The liver produces bile; the gall bladder stores and releases it.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1814,45,'A heterozygous tall plant is crossed with a dwarf plant. If tallness is dominant, what proportion of offspring is expected to be tall?','One quarter','One half','Three quarters','All offspring','B','Tt crossed with tt gives half Tt tall offspring and half tt dwarf offspring.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1815,45,'Which part of a flower receives pollen grains during pollination?','Anther','Stigma','Ovary','Filament','B','The stigma is the receptive surface for pollen grains.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1816,45,'Which process releases energy from glucose in the cells of animals?','Photosynthesis','Respiration','Transpiration','Excretion','B','Cellular respiration releases usable energy from glucose.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1817,45,'Which blood vessel carries blood away from the heart?','Vein','Artery','Capillary','Venule','B','Arteries carry blood away from the heart, irrespective of oxygen content.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1818,45,'A population of insects increases after its main predator becomes scarce. Which ecological relationship has changed?','Predation','Commensalism','Pollination','Parasitism','A','Reduced predation can allow prey numbers to rise.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1819,45,'Which structure in the human respiratory system is the main site of gaseous exchange?','Trachea','Bronchus','Alveolus','Larynx','C','Thin-walled alveoli provide a large surface area for oxygen and carbon dioxide exchange.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1820,45,'Which nutrient is the primary immediate source of energy in a balanced diet?','Carbohydrate','Vitamin','Mineral salt','Water','A','Carbohydrates are commonly broken down to provide energy for cellular activities.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1821,45,'What is the role of chlorophyll in a green leaf?','Absorb light energy','Transport sugars','Store mineral salts','Open the stomata','A','Chlorophyll absorbs light energy used in photosynthesis.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1822,45,'Which plant response causes a shoot to bend towards a source of light?','Geotropism','Phototropism','Hydrotropism','Thigmotropism','B','Phototropism is directional growth in response to light.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1823,45,'Which cells in the pancreas release insulin into the blood?','Beta cells','Red blood cells','Nerve cells','Goblet cells','A','Pancreatic beta cells produce insulin, which helps regulate blood glucose.',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1824,45,'Which feature of a fish helps it maintain balance and control movement in water?','Swim bladder only','Fins','Gill rakers','Scales','B','Fins provide steering, stability, and propulsion.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1825,45,'Which microorganism is commonly used in baking to make dough rise?','Yeast','Amoeba','Plasmodium','Rhizobium','A','Yeast ferments sugars and releases carbon dioxide, which expands dough.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1826,45,'Which term describes animals that maintain a relatively constant internal body temperature?','Ectothermic','Endothermic','Anaerobic','Aquatic','B','Endothermic animals generate and regulate body heat internally.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1827,45,'What is the main function of root hairs in a plant?','Absorb water and mineral ions','Make seeds','Carry sugars to flowers','Prevent pollination','A','Root hairs increase surface area for absorption from the soil.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1828,45,'Which structure prevents food from entering the trachea during swallowing?','Epiglottis','Diaphragm','Uvula','Bronchiole','A','The epiglottis folds over the airway during swallowing.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1829,45,'In a food chain, what is the original source of energy for most ecosystems?','The Sun','Soil minerals','Decomposers','Wind','A','Producers capture solar energy and make it available to other trophic levels.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1830,45,'Which process removes metabolic waste products from an organism?','Nutrition','Excretion','Assimilation','Reproduction','B','Excretion removes waste products formed by metabolism.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1831,45,'Which part of the nephron selectively reabsorbs useful substances from the filtrate?','Renal tubule','Ureter','Bladder','Renal pelvis','A','The renal tubule reabsorbs water, glucose, and ions according to the body\'s needs.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1832,45,'Which type of reproduction usually produces offspring genetically similar to one parent?','Sexual reproduction','Asexual reproduction','Cross-pollination','Fertilisation','B','Asexual reproduction involves one parent and usually produces genetically similar offspring.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1833,45,'Which gas is taken in by green plants for photosynthesis?','Oxygen','Carbon dioxide','Nitrogen','Hydrogen','B','Carbon dioxide is a raw material for photosynthesis.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1834,45,'Which type of joint allows movement in many directions at the shoulder?','Hinge joint','Ball-and-socket joint','Pivot joint','Fixed joint','B','The shoulder\'s ball-and-socket joint permits movement through a wide range of directions.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1835,45,'Why are antibiotics ineffective against influenza viruses?','Viruses have no cell-wall structures targeted by many antibiotics','Viruses are larger than bacteria','Viruses contain chlorophyll','Antibiotics only work in cold climates','A','Antibiotics target bacterial structures or processes; viruses reproduce inside host cells.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1836,45,'Which human cell part contains most of the genetic material?','Nucleus','Cell membrane','Ribosome','Lysosome','A','The nucleus contains chromosomes made of DNA in most human cells.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1837,45,'What is the name for the gradual change in inherited characteristics of populations over generations?','Ecological succession','Evolution','Homeostasis','Fermentation','B','Evolution describes inherited population changes across generations.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1838,45,'Which condition is required for seeds to germinate?','Water, oxygen and suitable temperature','Continuous bright light only','Carbon dioxide and salt','Complete submersion in water','A','Most seeds require moisture, oxygen, and a suitable temperature to germinate.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1839,45,'Which organism is a decomposer in a terrestrial ecosystem?','Mushroom','Hawk','Grass','Goat','A','Fungi such as mushrooms break down dead organic material.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1840,45,'What is the main benefit of vaccination to a population?','It can increase immunity and reduce transmission','It replaces all hygiene practices','It treats every disease after symptoms start','It prevents organisms from mutating','A','Vaccination can build immunity and reduce the spread of vaccine-preventable diseases.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1864,46,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1865,46,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1866,46,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1867,46,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1868,46,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1869,46,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1870,46,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1871,46,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1872,46,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1873,46,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1874,46,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1875,46,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1876,46,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1877,46,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1878,46,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1879,46,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1880,46,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1881,46,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1882,46,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1883,46,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1884,46,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1885,46,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1886,46,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1887,46,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1888,46,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1889,46,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1890,46,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1891,46,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1892,46,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1893,46,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1894,46,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1895,46,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1896,46,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1897,46,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1898,46,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1899,46,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1900,46,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1901,46,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1902,46,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1903,46,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1927,47,'Simplify 3(2x - 4) + 5.','6x - 12','6x - 7','6x - 17','5x - 7','B','Distribute 3 to get 6x - 12, then add 5 to obtain 6x - 7.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1928,47,'A rectangle has length 12 cm and width 5 cm. What is its area?','17 cm^2','34 cm^2','60 cm^2','120 cm^2','C','Area is length multiplied by width: 12 x 5 = 60 cm^2.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1929,47,'Solve 4y + 3 = 19.','y = 3','y = 4','y = 5','y = 7','B','Subtract 3 to get 4y = 16, then divide by 4.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1930,47,'What is the median of 2, 5, 7, 9, 12?','5','7','8','9','B','The ordered list has five values, so the middle value is 7.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1931,47,'Express 0.375 as a fraction in its simplest form.','3/4','3/8','5/8','15/40','B','0.375 = 375/1000; dividing numerator and denominator by 125 gives 3/8.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1932,47,'A bag contains 3 red and 5 blue counters. What is the probability of choosing a red counter?','3/5','5/8','3/8','1/3','C','There are 3 red counters among 8 counters in total.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1933,47,'Find the gradient of the line through (1, 2) and (5, 10).','1','2','4','8','B','Gradient = (10 - 2) / (5 - 1) = 8/4 = 2.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1934,47,'A triangle has angles 48 degrees and 67 degrees. Find the third angle.','55 degrees','65 degrees','75 degrees','85 degrees','B','Angles in a triangle sum to 180 degrees; 180 - 48 - 67 = 65 degrees.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1935,47,'Evaluate 2^3 x 2^2.','16','24','32','64','C','For equal bases, add exponents: 2^(3+2) = 2^5 = 32.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1936,47,'A shirt costs NGN 8,000 and is discounted by 15%. What is the sale price?','NGN 6,400','NGN 6,800','NGN 7,200','NGN 7,850','B','15% of NGN 8,000 is NGN 1,200; the sale price is NGN 6,800.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1937,47,'A shop marks a school bag at NGN 12,500 and offers a discount of 20 percent. What amount does a buyer pay after the discount?','NGN 9,500','NGN 10,000','NGN 10,500','NGN 11,000','B','Twenty percent of NGN 12,500 is NGN 2,500; subtracting it gives NGN 10,000.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1938,47,'A rectangular garden is 18 m long and 11 m wide. How many metres of fencing are needed to go once around it?','29 m','47 m','58 m','198 m','C','Perimeter is 2(length + width), so 2(18 + 11) = 58 m.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1939,47,'Solve the equation 5x - 7 = 3x + 9 and select the value of x.','6','7','8','9','C','Subtract 3x and add 7 on both sides: 2x = 16, hence x = 8.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1940,47,'The ratio of red counters to blue counters is 3:5. If there are 40 counters altogether, how many are blue?','15','20','25','30','C','There are 8 ratio parts; each part is 40/8 = 5, so blue counters total 5 x 5 = 25.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1941,47,'A class has 50 learners and 18 percent are absent on a particular day. How many learners are present?','39','41','43','45','B','Eighteen percent of 50 is 9; subtracting 9 from 50 leaves 41 learners present.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1942,47,'Five test scores are 6, 8, 9, 11 and 16. What is their arithmetic mean?','9','10','11','12','B','The total is 50; dividing by the five scores gives a mean of 10.',1.00,16);
INSERT  IGNORE INTO `cbt_questions` VALUES (1943,47,'A sequence begins 4, 9, 14, 19. If the same pattern continues, what is the next term?','22','23','24','25','C','The sequence increases by 5 each time, so the next term is 24.',1.00,17);
INSERT  IGNORE INTO `cbt_questions` VALUES (1944,47,'A trapezium has parallel sides of 8 cm and 14 cm and a perpendicular height of 6 cm. Find its area.','44 cm^2','60 cm^2','66 cm^2','84 cm^2','C','Area is half the sum of parallel sides times height: 0.5(8 + 14) x 6 = 66 cm^2.',1.00,18);
INSERT  IGNORE INTO `cbt_questions` VALUES (1945,47,'Solve simultaneously: x + y = 11 and x - y = 3. What is the value of x?','4','7','8','14','B','Adding the equations gives 2x = 14, so x = 7.',1.00,19);
INSERT  IGNORE INTO `cbt_questions` VALUES (1946,47,'A box contains 4 green and 6 yellow balls. One ball is chosen at random. What is the probability that it is green?','1/5','2/5','3/5','4/5','B','There are 4 favourable outcomes out of 10 equally likely balls, giving 4/10 = 2/5.',1.00,20);
INSERT  IGNORE INTO `cbt_questions` VALUES (1947,47,'A principal of NGN 30,000 is invested at 8 percent simple interest per year for 2 years. What is the interest earned?','NGN 2,400','NGN 4,800','NGN 6,000','NGN 34,800','B','Simple interest is PRT/100 = 30,000 x 8 x 2 / 100 = NGN 4,800.',1.00,21);
INSERT  IGNORE INTO `cbt_questions` VALUES (1948,47,'A bus travels 180 km in 3 hours at a constant speed. What is its average speed?','45 km/h','50 km/h','60 km/h','90 km/h','C','Average speed is distance divided by time: 180/3 = 60 km/h.',1.00,22);
INSERT  IGNORE INTO `cbt_questions` VALUES (1949,47,'Factorise the quadratic expression x^2 + 7x + 12 completely.','(x + 2)(x + 6)','(x + 3)(x + 4)','(x - 3)(x - 4)','(x + 1)(x + 12)','B','The numbers 3 and 4 multiply to 12 and add to 7, giving (x + 3)(x + 4).',1.00,23);
INSERT  IGNORE INTO `cbt_questions` VALUES (1950,47,'A recipe uses 3/4 cup of flour. A cook prepares half the recipe. How much flour is needed?','1/4 cup','3/8 cup','1/2 cup','2/3 cup','B','Half of 3/4 is 3/8 cup.',1.00,24);
INSERT  IGNORE INTO `cbt_questions` VALUES (1951,47,'Three interior angles of a quadrilateral are 82 degrees, 95 degrees and 103 degrees. Find the fourth angle.','70 degrees','80 degrees','90 degrees','100 degrees','B','The interior angles sum to 360 degrees; 360 - 82 - 95 - 103 = 80 degrees.',1.00,25);
INSERT  IGNORE INTO `cbt_questions` VALUES (1952,47,'A storage carton measures 12 cm by 8 cm by 5 cm. What is its volume?','25 cm^3','96 cm^3','240 cm^3','480 cm^3','D','Volume of a cuboid is length x width x height: 12 x 8 x 5 = 480 cm^3.',1.00,26);
INSERT  IGNORE INTO `cbt_questions` VALUES (1953,47,'A straight line passes through (0, 3) and (2, 7). What is its gradient?','1','2','3','4','B','Gradient is change in y divided by change in x: (7 - 3)/(2 - 0) = 2.',1.00,27);
INSERT  IGNORE INTO `cbt_questions` VALUES (1954,47,'The cost of 7 identical notebooks is NGN 2,100. At the same rate, what is the cost of 12 notebooks?','NGN 2,700','NGN 3,000','NGN 3,300','NGN 3,600','D','One notebook costs NGN 300, so 12 cost NGN 3,600.',1.00,28);
INSERT  IGNORE INTO `cbt_questions` VALUES (1955,47,'A map scale is 1 cm to 5 km. Two towns are 7.4 cm apart on the map. What is the actual distance?','12.4 km','25 km','35 km','37 km','D','Multiply the map distance by 5 km per centimetre: 7.4 x 5 = 37 km.',1.00,29);
INSERT  IGNORE INTO `cbt_questions` VALUES (1956,47,'Write 0.00056 in standard form.','5.6 x 10^-3','5.6 x 10^-4','56 x 10^-5','0.56 x 10^-3','B','Move the decimal four places right to get 5.6, so the power is 10^-4.',1.00,30);
INSERT  IGNORE INTO `cbt_questions` VALUES (1957,47,'Solve x^2 - 9 = 0 and choose the pair of roots.','x = 3 only','x = -3 only','x = 3 or x = -3','x = 9 or x = -9','C','x^2 = 9 has two roots, 3 and -3.',1.00,31);
INSERT  IGNORE INTO `cbt_questions` VALUES (1958,47,'A data set has values 1, 2 and 3 with frequencies 2, 3 and 5 respectively. What is the mean?','2','2.3','2.5','3','B','The weighted total is 1x2 + 2x3 + 3x5 = 23; total frequency is 10, giving 2.3.',1.00,32);
INSERT  IGNORE INTO `cbt_questions` VALUES (1959,47,'A sum of NGN 9,000 is shared in the ratio 2:3:4. What is the largest share?','NGN 2,000','NGN 3,000','NGN 4,000','NGN 5,000','C','There are 9 parts, each worth NGN 1,000; the largest share is 4 parts.',1.00,33);
INSERT  IGNORE INTO `cbt_questions` VALUES (1960,47,'A lesson begins at 10:35 and lasts 1 hour 48 minutes. At what time does it end?','12:13','12:23','12:33','12:43','B','Adding 1 hour gives 11:35; adding 48 minutes gives 12:23.',1.00,34);
INSERT  IGNORE INTO `cbt_questions` VALUES (1961,47,'A cylinder has radius 3 cm and height 10 cm. Using pi = 22/7, find its volume to 1 decimal place.','94.3 cm^3','188.6 cm^3','282.9 cm^3','314.2 cm^3','C','Volume is pi r^2 h = (22/7) x 9 x 10, approximately 282.9 cm^3.',1.00,35);
INSERT  IGNORE INTO `cbt_questions` VALUES (1962,47,'Find the gradient of a line perpendicular to a line with gradient 2.','-2','-1/2','1/2','2','B','Perpendicular non-vertical lines have gradients whose product is -1; the required gradient is -1/2.',1.00,36);
INSERT  IGNORE INTO `cbt_questions` VALUES (1963,47,'A phone valued at NGN 80,000 loses 10 percent of its value in one year. What is its value after that year?','NGN 70,000','NGN 72,000','NGN 74,000','NGN 78,000','B','Ten percent is NGN 8,000; subtracting this from NGN 80,000 gives NGN 72,000.',1.00,37);
INSERT  IGNORE INTO `cbt_questions` VALUES (1964,47,'Solve the inequality 3x + 2 < 14 for x.','x < 4','x > 4','x < 5','x > 5','A','Subtract 2 to get 3x < 12, then divide by 3 to get x < 4.',1.00,38);
INSERT  IGNORE INTO `cbt_questions` VALUES (1965,47,'In a right-angled triangle, the side opposite angle theta is 6 cm and the hypotenuse is 10 cm. Find sin theta.','3/5','4/5','5/3','5/4','A','Sine is opposite divided by hypotenuse: 6/10 = 3/5.',1.00,39);
INSERT  IGNORE INTO `cbt_questions` VALUES (1966,47,'If log base 10 of x equals 2, what is x?','10','20','100','1,000','C','log10(x) = 2 means x = 10^2 = 100.',1.00,40);
INSERT  IGNORE INTO `cbt_questions` VALUES (1967,48,'Neither the teacher nor the students ___ in the hall when the bell rang.','was','were','is','has been','B','With “neither … nor”, the verb agrees with the nearer subject, “students”, which is plural.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1968,48,'She has been living in Abuja ___ 2015.','for','since','from','at','B','“Since” introduces a point in time; “for” introduces a length of time.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1969,48,'Choose the word nearest in meaning to “candid”.','secretive','frank','angry','careful','B','Candid means open and honest, that is, frank.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1970,48,'Choose the word opposite in meaning to “scarce”.','rare','plentiful','small','costly','B','Scarce means in short supply; the opposite is plentiful.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1971,48,'What is the plural of “criterion”?','criterions','criteria','criterias','criterium','B','“Criterion” is singular; “criteria” is the plural.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1972,48,'If I ___ you, I would apologise to her.','am','was','were','be','C','Hypothetical conditions take the subjunctive “were” for all persons.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1973,48,'Tolu is very good ___ mathematics.','in','at','on','with','B','The fixed expression is “good at” a subject or skill.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1974,48,'Choose the correctly spelt word.','accomodation','acommodation','accommodation','acomodation','C','“Accommodation” has a double c and a double m.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1975,48,'“The examination was a piece of cake” means the examination was','very difficult','very easy','too long','well organised','B','“A piece of cake” is an idiom meaning something very easy.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1976,48,'The students, together with their teacher, ___ going on an excursion tomorrow.','are','is','was','has','A','Phrases like “together with their teacher” do not change the subject; “students” is plural, so “are”.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1977,48,'Identify the figure of speech: “The wind whispered through the trees.”','Simile','Metaphor','Personification','Hyperbole','C','Giving the wind a human action (whispering) is personification.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1978,48,'You are coming to the party, ___?','are you','aren’t you','isn’t it','don’t you','B','A positive statement takes a negative tag with the same auxiliary: “aren’t you?”',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1979,48,'Which word has a different vowel sound from the others?','seat','feet','heat','bread','D','“Bread” has the short /e/ sound; the others have the long /iː/ sound.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1980,48,'Which word is stressed on the second syllable?','table','begin','mother','window','B','be-GIN is stressed on the second syllable; the others are stressed on the first.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1981,48,'“To let the cat out of the bag” means to','release a pet','reveal a secret','cause trouble','run away','B','The idiom means to disclose something that was meant to be kept secret.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1982,49,'The SI unit of force is the','joule','newton','watt','pascal','B','Force = mass × acceleration, measured in newtons (1 N = 1 kg·m/s²).',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1983,49,'A car accelerates uniformly from rest to 20 m/s in 5 s. Its acceleration is','2 m/s²','4 m/s²','5 m/s²','100 m/s²','B','a = (v − u) ÷ t = (20 − 0) ÷ 5 = 4 m/s².',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1984,49,'A body of mass 2 kg moves with a velocity of 3 m/s. Its kinetic energy is','3 J','6 J','9 J','18 J','C','KE = ½mv² = ½ × 2 × 3² = 9 J.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (1985,49,'Calculate the work done in lifting a 5 kg mass through a height of 4 m. (g = 10 m/s²)','20 J','50 J','200 J','2000 J','C','W = mgh = 5 × 10 × 4 = 200 J.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (1986,49,'A machine does 600 J of work in 30 s. Its power is','20 W','180 W','570 W','18 000 W','A','P = W ÷ t = 600 ÷ 30 = 20 W.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (1987,49,'Pressure is defined as','force × area','force ÷ area','mass ÷ volume','force × distance','B','P = F ÷ A, measured in pascals (N/m²).',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (1988,49,'Which mode of heat transfer does not need a material medium?','Conduction','Convection','Radiation','Evaporation','C','Radiation travels as electromagnetic waves, even through a vacuum.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (1989,49,'A wave has a frequency of 50 Hz and a wavelength of 4 m. Its speed is','12.5 m/s','54 m/s','200 m/s','46 m/s','C','v = fλ = 50 × 4 = 200 m/s.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (1990,49,'The image formed by a plane mirror is','real and inverted','virtual and upright','real and magnified','virtual and diminished','B','A plane mirror forms a virtual, upright image the same size as the object.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (1991,49,'A current of 2 A flows through a 6 Ω resistor. The potential difference across it is','3 V','4 V','8 V','12 V','D','V = IR = 2 × 6 = 12 V.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (1992,49,'Two 4 Ω resistors are connected in parallel. Their effective resistance is','0.5 Ω','2 Ω','4 Ω','8 Ω','B','1/R = 1/4 + 1/4 = 1/2, so R = 2 Ω.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (1993,49,'Which of these materials is ferromagnetic?','Copper','Aluminium','Iron','Brass','C','Iron is strongly attracted to magnets and can be magnetised.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (1994,49,'The boiling point of a pure liquid depends mainly on the','volume of the liquid','external pressure','size of the container','colour of the liquid','B','Boiling point rises as external pressure increases and falls as it decreases.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (1995,49,'An alpha particle is identical to the nucleus of','hydrogen','helium','lithium','carbon','B','An alpha particle has 2 protons and 2 neutrons, like a helium nucleus.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (1996,49,'Which of these is a vector quantity?','Mass','Speed','Displacement','Energy','C','Displacement has both magnitude and direction.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (1997,50,'The atomic number of an element is the number of','neutrons','protons','nucleons','electron shells','B','Atomic number = number of protons in the nucleus.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (1998,50,'An atom has 11 protons and 12 neutrons. Its mass number is','1','11','12','23','D','Mass number = protons + neutrons = 11 + 12 = 23.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (1999,50,'Elements in the same group of the periodic table have the same number of','protons','neutrons','valence electrons','electron shells','C','Group members have the same number of outer electrons, so they react similarly.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (2000,50,'The bond between sodium and chlorine in sodium chloride is','covalent','ionic','metallic','hydrogen','B','Sodium transfers an electron to chlorine, forming Na⁺ and Cl⁻ ions.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (2001,50,'A solution with a pH of 2 is','strongly acidic','weakly acidic','neutral','alkaline','A','pH values far below 7 indicate strong acidity.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (2002,50,'The reaction of an acid with a base to form salt and water is called','oxidation','neutralisation','hydrolysis','esterification','B','Acid + base → salt + water is neutralisation.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (2003,50,'What is the molar mass of CO₂? (C = 12, O = 16)','28 g/mol','32 g/mol','44 g/mol','60 g/mol','C','12 + (2 × 16) = 44 g/mol.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (2004,50,'How many moles are in 36 g of water? (H = 1, O = 16)','0.5','1','2','3','C','Molar mass of H₂O = 18 g/mol, so 36 ÷ 18 = 2 mol.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (2005,50,'The best method to obtain pure water from salt solution is','filtration','distillation','decantation','sublimation','B','Distillation boils off the water and condenses it, leaving the salt behind.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (2006,50,'At constant temperature, the volume of a fixed mass of gas is inversely proportional to its pressure. This is','Charles’ law','Boyle’s law','Avogadro’s law','Graham’s law','B','Boyle’s law: PV is constant at fixed temperature.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (2007,50,'Oxidation is the','gain of electrons','loss of electrons','gain of protons','loss of neutrons','B','OIL RIG: Oxidation Is Loss of electrons, Reduction Is Gain.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (2008,50,'The general formula of the alkanes is','CₙH₂ₙ','CₙH₂ₙ₊₂','CₙH₂ₙ₋₂','CₙHₙ','B','Alkanes are saturated hydrocarbons, CₙH₂ₙ₊₂, for example methane, CH₄.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (2009,50,'Ethanol belongs to the homologous series of','alkanes','alkenes','alkanols','alkanoic acids','C','Ethanol, C₂H₅OH, contains the –OH group of the alkanols.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (2010,50,'Which of these increases the rate of a chemical reaction?','Lowering the temperature','Using larger lumps of solid','Adding a suitable catalyst','Diluting the reactants','C','A catalyst provides a pathway with a lower activation energy.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (2011,50,'For iron to rust, it must be exposed to','oxygen only','water only','both oxygen and water','carbon dioxide only','C','Rusting needs both oxygen and water.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (2012,51,'The control centre of the cell is the','cytoplasm','nucleus','cell membrane','vacuole','B','The nucleus contains the genetic material and controls cell activities.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (2013,51,'Which organelle is the site of aerobic respiration?','Ribosome','Chloroplast','Mitochondrion','Golgi body','C','Mitochondria release energy from food by aerobic respiration.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (2014,51,'Plant cells differ from animal cells by having a','nucleus','cell wall','cell membrane','cytoplasm','B','Plant cells have a cellulose cell wall; animal cells do not.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (2015,51,'Photosynthesis takes place mainly in the','roots','stem','leaves','flowers','C','Leaves contain most of the plant’s chloroplasts.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (2016,51,'The gas released during photosynthesis is','carbon dioxide','nitrogen','oxygen','hydrogen','C','Water molecules are split during photosynthesis, releasing oxygen.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (2017,51,'A deficiency of vitamin C causes','rickets','scurvy','beriberi','night blindness','B','Lack of vitamin C causes scurvy, with bleeding gums.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (2018,51,'The blood vessels that carry blood away from the heart are','veins','arteries','capillaries','lymph vessels','B','Arteries carry blood away from the heart; veins return it.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (2019,51,'Which blood component helps blood to clot?','Red blood cells','White blood cells','Platelets','Plasma proteins only','C','Platelets release substances that start the clotting process.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (2020,51,'The organ that removes urea from the blood is the','liver','lungs','kidney','skin','C','The kidneys filter urea from the blood into urine.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (2021,51,'In flowering plants, the male gametes are carried in the','ovule','pollen grain','stigma','ovary','B','Pollen grains carry the male gametes to the ovule.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (2022,51,'The observable characteristics of an organism make up its','genotype','phenotype','allele','chromosome','B','The phenotype is what can be observed; the genotype is the genetic make-up.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (2023,51,'Two heterozygous tall pea plants (Tt × Tt) are crossed. The ratio of tall to short offspring is','1 : 1','3 : 1','1 : 2','4 : 0','B','The offspring are TT, Tt, Tt and tt: three tall to one short.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (2024,51,'Organisms that make their own food are called','consumers','decomposers','producers','parasites','C','Producers, mainly green plants, make food by photosynthesis.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (2025,51,'The feeding position an organism occupies in a food chain is its','habitat','niche','trophic level','population','C','A trophic level is a feeding level in a food chain.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (2026,51,'Malaria is transmitted by the female','Aedes mosquito','Anopheles mosquito','Culex mosquito','tsetse fly','B','The female Anopheles mosquito carries the Plasmodium parasite.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (2027,52,'The basic economic problem arises because of','money','scarcity','taxation','inflation','B','Wants are unlimited but resources are scarce, so choices must be made.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (2028,52,'Opportunity cost is the','money cost of a good','next best alternative forgone','total cost of production','price of a substitute','B','It is the value of the next best alternative given up when making a choice.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (2029,52,'According to the law of demand, when price rises, quantity demanded','rises','falls','stays the same','doubles','B','Other things being equal, price and quantity demanded move in opposite directions.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (2030,52,'An increase in the cost of production will most likely shift the supply curve to the','right','left','vertical','origin','B','Higher costs reduce the quantity supplied at every price.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (2031,52,'A 10% fall in price leads to a 20% rise in quantity demanded. Demand is','perfectly inelastic','inelastic','unitary elastic','elastic','D','PED = 20% ÷ 10% = 2, which is greater than 1, so demand is elastic.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (2032,52,'The factor of production that organises the others and bears risk is','land','labour','capital','the entrepreneur','D','The entrepreneur combines land, labour and capital and bears the risk.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (2033,52,'Which of these is not a function of money?','Medium of exchange','Store of value','Unit of account','Factor of production','D','Money is not a factor of production.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (2034,52,'A persistent rise in the general price level is called','deflation','inflation','devaluation','depreciation','B','Inflation is a sustained increase in the general price level.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (2035,52,'The apex bank in Nigeria is the','First Bank of Nigeria','Central Bank of Nigeria','Bank of Industry','Nigerian Exchange','B','The Central Bank of Nigeria regulates banks and issues the currency.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (2036,52,'A market with only one seller of a product with no close substitutes is','perfect competition','oligopoly','monopoly','monopsony','C','A monopoly has a single seller.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (2037,52,'Gross Domestic Product measures the total value of','goods imported','final goods and services produced within a country','government spending only','money in circulation','B','GDP is the value of final output produced within a country’s borders in a period.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (2038,52,'A country with too few people to make the best use of its resources is','optimum populated','over-populated','under-populated','an ageing population','C','Under-population means too few people to fully use available resources.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (2039,52,'The direct exchange of goods for goods without money is','barter','credit trade','auction','dumping','A','Barter is the direct exchange of goods and services.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (2040,52,'A tax whose rate increases as income increases is','regressive','proportional','progressive','indirect','C','A progressive tax takes a higher percentage from higher incomes.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (2041,52,'The extra satisfaction from consuming one more unit of a good is','total utility','marginal utility','average utility','zero utility','B','Marginal utility is the change in total utility from one additional unit.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (2042,53,'The ability to make others obey commands is','authority','power','legitimacy','influence','B','Power is the capacity to compel obedience; authority is the recognised right to use it.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (2043,53,'Sovereignty means the','supreme power of the state','independence of the judiciary','freedom of the press','rule by the military','A','Sovereignty is the supreme and final legal authority of a state.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (2044,53,'A system in which citizens elect people to govern on their behalf is','direct democracy','representative democracy','monarchy','oligarchy','B','Representative democracy works through elected representatives.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (2045,53,'Which of these is a feature of the rule of law?','Supremacy of the law','Arbitrary arrest','Rule by decree','Immunity for all citizens','A','Under the rule of law, the law is supreme and applies equally to everyone.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (2046,53,'The theory of separation of powers was popularised by','John Locke','Baron de Montesquieu','Karl Marx','Thomas Hobbes','B','Montesquieu set it out in “The Spirit of the Laws” (1748).',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (2047,53,'The organ of government that interprets the law is the','legislature','executive','judiciary','civil service','C','The courts interpret laws and settle disputes.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (2048,53,'A system in which power is shared between a central government and component units is','unitary','confederal','federal','presidential','C','Federalism divides power between central and state governments, as in Nigeria.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (2049,53,'A constitution that requires a special procedure to amend is','flexible','rigid','unwritten','customary','B','A rigid constitution cannot be changed by an ordinary law-making process.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (2050,53,'The body that conducts federal elections in Nigeria is','NBC','INEC','NPC','EFCC','B','The Independent National Electoral Commission conducts federal elections.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (2051,53,'Nigeria became a republic in','1960','1963','1966','1979','B','Nigeria became a republic on 1 October 1963.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (2052,53,'The Northern and Southern Protectorates of Nigeria were amalgamated in','1900','1914','1922','1960','B','Lord Lugard amalgamated the protectorates in 1914.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (2053,53,'A system in which only one political party is legally allowed is','multi-party','two-party','one-party','non-party','C','In a one-party system, only one party may operate legally.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (2054,53,'Citizenship granted to a foreigner after residing in a country for a required period is by','birth','naturalisation','descent','honour','B','Naturalisation grants citizenship to qualifying foreign residents.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (2055,53,'The main aim of pressure groups is to','win elections','form the government','influence government policy','conduct elections','C','Pressure groups seek to influence policy, not to hold office.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (2056,53,'The Economic Community of West African States (ECOWAS) was established in','1963','1975','1960','1999','B','ECOWAS was founded by the Treaty of Lagos in 1975.',1.00,15);
INSERT  IGNORE INTO `cbt_questions` VALUES (2057,54,'Which of these is an input device?','Monitor','Printer','Keyboard','Speaker','C','A keyboard sends data into the computer; the others present output.',1.00,1);
INSERT  IGNORE INTO `cbt_questions` VALUES (2058,54,'The part of the computer that carries out instructions is the','monitor','central processing unit (CPU)','hard disk','keyboard','B','The CPU fetches, decodes and executes program instructions.',1.00,2);
INSERT  IGNORE INTO `cbt_questions` VALUES (2059,54,'Which memory loses its contents when the computer is switched off?','ROM','RAM','Hard disk','Flash drive','B','RAM is volatile; it needs power to keep data.',1.00,3);
INSERT  IGNORE INTO `cbt_questions` VALUES (2060,54,'How many bits make one byte?','4','8','16','1024','B','One byte is a group of 8 bits.',1.00,4);
INSERT  IGNORE INTO `cbt_questions` VALUES (2061,54,'What is the decimal value of the binary number 1010?','8','10','12','1010','B','1×8 + 0×4 + 1×2 + 0×1 = 10.',1.00,5);
INSERT  IGNORE INTO `cbt_questions` VALUES (2062,54,'One kilobyte (KB) is equal to','100 bytes','1000 bits','1024 bytes','1024 kilobits','C','In computing, 1 KB = 2¹⁰ = 1024 bytes.',1.00,6);
INSERT  IGNORE INTO `cbt_questions` VALUES (2063,54,'Which of these is an operating system?','Microsoft Word','Windows','Google Chrome','Microsoft Excel','B','Windows manages the hardware and runs other programs; the others are applications.',1.00,7);
INSERT  IGNORE INTO `cbt_questions` VALUES (2064,54,'A program used to type and format letters and reports is a','spreadsheet','word processor','database','web browser','B','Word processors, such as Microsoft Word, create and format text documents.',1.00,8);
INSERT  IGNORE INTO `cbt_questions` VALUES (2065,54,'In a spreadsheet, the formula =SUM(A1:A3) will','multiply A1 by A3','add the values in A1, A2 and A3','count the cells A1 to A3','find the average of A1 and A3','B','SUM adds all values in the range A1 to A3.',1.00,9);
INSERT  IGNORE INTO `cbt_questions` VALUES (2066,54,'The software used to view web pages is called a','search engine','web browser','web server','modem','B','A browser (for example Chrome or Firefox) displays web pages.',1.00,10);
INSERT  IGNORE INTO `cbt_questions` VALUES (2067,54,'What does “URL” stand for?','Universal Reference Link','Uniform Resource Locator','Unified Resource Line','User Resource Locator','B','A URL is the address of a resource on the web.',1.00,11);
INSERT  IGNORE INTO `cbt_questions` VALUES (2068,54,'A network that connects computers within one building, such as a school, is a','WAN','LAN','MAN','PAN','B','A Local Area Network (LAN) covers a small area like a building.',1.00,12);
INSERT  IGNORE INTO `cbt_questions` VALUES (2069,54,'A program designed to damage files or spread to other computers is a','compiler','virus','browser','driver','B','A computer virus is malicious software that spreads and causes damage.',1.00,13);
INSERT  IGNORE INTO `cbt_questions` VALUES (2070,54,'A step-by-step set of instructions for solving a problem is called','an algorithm','a database','a network','a peripheral','A','An algorithm is an ordered set of steps that solves a problem.',1.00,14);
INSERT  IGNORE INTO `cbt_questions` VALUES (2071,54,'Who is often called the “father of the computer”?','Bill Gates','Charles Babbage','Tim Berners-Lee','Alan Turing','B','Charles Babbage designed the Analytical Engine, an early mechanical computer.',1.00,15);
